import { NavigationContainer, useNavigationContainerRef } from "@react-navigation/native";
import { createNativeStackNavigator } from "@react-navigation/native-stack";
import * as SplashScreen from "expo-splash-screen";
import { StatusBar } from "expo-status-bar";
import { PostHogErrorBoundary, PostHogProvider } from "posthog-react-native";
import { type ReactNode, useEffect, useRef } from "react";
import { StyleSheet, View } from "react-native";
import { SafeAreaProvider } from "react-native-safe-area-context";
import { analytics } from "@/config/analytics";
import { posthog } from "@/config/posthog";
import { AppLockGate } from "@/modules/auth";
import { sweepUnreferencedMedia } from "@/modules/entry";
import { ProfileProvider } from "@/modules/profile";
import type { RootStackParamList } from "@/navigation";
import { Compose } from "@/screens/compose";
import { Day } from "@/screens/day";
import {
  Settings,
  SettingsAbout,
  SettingsAccent,
  SettingsAccessibility,
  SettingsAppearance,
  SettingsPrivacy,
  SettingsProfile,
  SettingsTheme,
  SettingsTimeline,
  SettingsTypography,
} from "@/screens/settings";
import { Tag } from "@/screens/tag";
import { Timeline } from "@/screens/timeline";
import { Welcome } from "@/screens/welcome";
import { AudioProvider } from "@/services/audio";
import { Layout, ThemedText } from "@/shared/components";
import { useAppBootstrap } from "@/shared/hooks";
import { logDevWarning, reportError } from "@/shared/utils";
import { AppProviders, space, useNavigationTheme, useTheme } from "@/theme";

/** Holds the splash screen until local bootstrap (fonts + preferences) finishes. */
function BootstrapGate({
  ready,
  databaseUnavailable,
  backgroundColor,
  children,
}: {
  ready: boolean;
  databaseUnavailable: boolean;
  backgroundColor: string;
  children: ReactNode;
}) {
  useEffect(() => {
    if (!ready) return;
    SplashScreen.hideAsync().catch((error) => logDevWarning("bootstrap:hideSplash", error));
    // The unavailable-database screen promises nothing is touched, so cleanup waits for a working one.
    if (databaseUnavailable) return;
    sweepUnreferencedMedia().catch((error) => reportError("bootstrap:sweepMedia", error));
  }, [ready, databaseUnavailable]);

  if (!ready) return <View style={{ flex: 1, backgroundColor }} />;
  return <>{children}</>;
}

SplashScreen.setOptions({ duration: 400, fade: true });
SplashScreen.preventAutoHideAsync().catch((error) => {
  logDevWarning("startup:preventAutoHideAsync", error);
});

const Stack = createNativeStackNavigator<RootStackParamList>();

/** Stands in for the whole app when the database cannot open; it reads and writes nothing. */
function DatabaseUnavailable() {
  const { theme, mode } = useTheme();

  return (
    <View style={[styles.unavailable, { backgroundColor: theme.colors.background }]}>
      <StatusBar style={mode === "dark" ? "light" : "dark"} />
      <ThemedText
        weight="semibold"
        accessibilityRole="header"
        style={[theme.typography.emptyTitle, styles.centered, { color: theme.colors.text }]}
      >
        OpenLog can't open your timeline
      </ThemedText>
      <ThemedText
        style={[theme.typography.emptyBody, styles.centered, { color: theme.colors.textSecondary }]}
      >
        Nothing has been changed or deleted. Close OpenLog completely and open it again. If this
        keeps happening, update OpenLog to the latest version. Please don't uninstall it, as that
        would remove everything stored on this device.
      </ThemedText>
    </View>
  );
}

function AppContent({ showWelcome }: { showWelcome: boolean }) {
  const { theme, mode } = useTheme();
  const navTheme = useNavigationTheme();
  const navigationRef = useNavigationContainerRef<RootStackParamList>();
  const routeNameRef = useRef<string | undefined>(undefined);
  const navigator = (
    <AppNavigator showWelcome={showWelcome} backgroundColor={theme.colors.background} />
  );

  // Official React Navigation screen tracking: onReady fires for the initial
  // route, onStateChange for every navigation after that.
  const trackCurrentScreen = () => {
    const name = navigationRef.current?.getCurrentRoute()?.name;
    if (!name || routeNameRef.current === name) return;
    routeNameRef.current = name;
    analytics.screen(name);
  };

  return (
    <View style={{ flex: 1, backgroundColor: theme.colors.background }}>
      <NavigationContainer
        ref={navigationRef}
        theme={navTheme}
        onReady={trackCurrentScreen}
        onStateChange={trackCurrentScreen}
      >
        <StatusBar style={mode === "dark" ? "light" : "dark"} />
        {posthog ? (
          <PostHogProvider client={posthog} autocapture={false}>
            <PostHogErrorBoundary
              fallback={<View style={{ flex: 1, backgroundColor: theme.colors.background }} />}
            >
              {navigator}
            </PostHogErrorBoundary>
          </PostHogProvider>
        ) : (
          navigator
        )}
      </NavigationContainer>
    </View>
  );
}

function AppNavigator({
  showWelcome,
  backgroundColor,
}: {
  showWelcome: boolean;
  backgroundColor: string;
}) {
  return (
    <Stack.Navigator
      initialRouteName={showWelcome ? "Welcome" : "Timeline"}
      screenOptions={{
        contentStyle: { backgroundColor },
        animation: "slide_from_right",
      }}
    >
      <Stack.Screen name="Welcome" component={Welcome} options={{ headerShown: false }} />
      <Stack.Screen name="Timeline" component={Timeline} options={{ headerShown: false }} />
      <Stack.Screen name="Day" component={Day} options={{ headerShown: false }} />
      <Stack.Screen name="Tag" component={Tag} options={{ headerShown: false }} />
      <Stack.Screen name="Compose" component={Compose} options={{ headerShown: false }} />
      <Stack.Screen
        name="Settings"
        component={Settings}
        options={{
          title: "Settings",
          headerBackTitle: "Back",
          headerShadowVisible: false,
        }}
      />
      {/* Settings categories — each pushes with the default back title
          ("Settings" on iOS, arrow on Android). */}
      <Stack.Screen
        name="SettingsProfile"
        component={SettingsProfile}
        options={{ title: "Profile", headerShadowVisible: false }}
      />
      <Stack.Screen
        name="SettingsAppearance"
        component={SettingsAppearance}
        options={{ title: "Appearance", headerShadowVisible: false }}
      />
      <Stack.Screen
        name="SettingsTheme"
        component={SettingsTheme}
        options={{ title: "Theme", headerShadowVisible: false }}
      />
      <Stack.Screen
        name="SettingsAccent"
        component={SettingsAccent}
        options={{ title: "Accent Color", headerShadowVisible: false }}
      />
      <Stack.Screen
        name="SettingsTypography"
        component={SettingsTypography}
        options={{ title: "Typography", headerShadowVisible: false }}
      />
      <Stack.Screen
        name="SettingsTimeline"
        component={SettingsTimeline}
        options={{ title: "Timeline & Editor", headerShadowVisible: false }}
      />
      <Stack.Screen
        name="SettingsAccessibility"
        component={SettingsAccessibility}
        options={{ title: "Accessibility", headerShadowVisible: false }}
      />
      <Stack.Screen
        name="SettingsPrivacy"
        component={SettingsPrivacy}
        options={{ title: "Privacy & Data", headerShadowVisible: false }}
      />
      <Stack.Screen
        name="SettingsAbout"
        component={SettingsAbout}
        options={{ title: "About", headerShadowVisible: false }}
      />
    </Stack.Navigator>
  );
}

export default function App() {
  const {
    ready,
    preferences,
    backgroundColor,
    userName,
    onboardingCompleted,
    databaseUnavailable,
  } = useAppBootstrap();
  // Welcome shows only when onboarding was never finished or skipped.
  const showWelcome = !userName && !onboardingCompleted;

  return (
    <SafeAreaProvider>
      <BootstrapGate
        ready={ready}
        databaseUnavailable={databaseUnavailable}
        backgroundColor={backgroundColor}
      >
        <Layout>
          <AppProviders initialPreferences={preferences}>
            {databaseUnavailable ? (
              <DatabaseUnavailable />
            ) : (
              <ProfileProvider initialName={userName}>
                <AudioProvider>
                  <AppLockGate>
                    <AppContent showWelcome={showWelcome} />
                  </AppLockGate>
                </AudioProvider>
              </ProfileProvider>
            )}
          </AppProviders>
        </Layout>
      </BootstrapGate>
    </SafeAreaProvider>
  );
}

const styles = StyleSheet.create({
  unavailable: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
    paddingHorizontal: space.xxxl,
    gap: space.md,
  },
  centered: { textAlign: "center" },
});

import { posthog } from "@/config/posthog";

type AnalyticsProperties = Record<string, string | number | boolean | null>;

export const analytics = {
  capture(event: string, properties?: AnalyticsProperties) {
    posthog?.capture(event, properties);
  },
  screen(name?: string) {
    if (name) posthog?.screen(name);
  },
};

import PostHog from "posthog-react-native";

const projectToken = process.env.EXPO_PUBLIC_POSTHOG_PROJECT_TOKEN;

// Set by eas.json build profiles; anything not built as production is development.
const env = process.env.EXPO_PUBLIC_APP_ENV === "production" ? "production" : "development";

// Dev bundles served by Metro never report: their events would pollute the
// project, and their flush failures surface as noise in the dev overlay.
const client =
  projectToken && !__DEV__
    ? new PostHog(projectToken, {
        host: "https://us.i.posthog.com",
        // Interaction autocapture is disabled; analytics and diagnostics are explicit.
        captureAppLifecycleEvents: true,
        enableSessionReplay: false,
        errorTracking: {
          autocapture: { uncaughtExceptions: true, unhandledRejections: true, console: false },
        },
      })
    : null;

client?.register({ Environment: env });

export const posthog = client;

import { File, Paths } from "expo-file-system";
import * as Sharing from "expo-sharing";
import { useEffect, useState } from "react";
import { ActivityIndicator, Alert, Pressable, StyleSheet, Switch, View } from "react-native";

import { analytics } from "@/config/analytics";
import { useEntries } from "@/modules/entry";
import {
  confirmDestructive,
  SettingsGroup,
  SettingsRow,
  SettingsScreenScroll,
} from "@/modules/settings";
import {
  authenticate,
  type EnrolledAuthLevel,
  getEnrolledAuthLevel,
  useBiometricLock,
} from "@/services/auth";
import {
  type ArchiveCounts,
  cancelActiveBackup,
  cancelActiveImport,
  copyBackupToDirectory,
  exportBackupArchive,
  hasLocalContentForImport,
  type InspectBackupResult,
  importBackupArchive,
  inspectBackupArchive,
  MissingBackupMediaError,
  pickBackupArchiveFile,
  pickBackupDestinationDirectory,
  setExportController,
  setImportController,
  useBackupStatus,
} from "@/services/backup";
import {
  dismissBackupProgressNotification,
  notifyBackupError,
  notifyBackupExportComplete,
  notifyBackupImportComplete,
  notifyBackupProgress,
} from "@/services/notifications";
import { ThemedText } from "@/shared/components/ThemedText";
import { logDevWarning, reportError } from "@/shared/utils";
import { press, space, typography, useTheme } from "@/theme";

const IMPORT_FAILURE_MESSAGE =
  "Import couldn’t complete, and your current timeline was not changed. Check the backup file and available storage, then try again.";

/**
 * Privacy & data category screen — everything about trust: the biometric
 * app lock under SECURITY, backup/export under DATA BACKUP,
 * and storage management under STORAGE.
 */
export function PrivacySettingsScreen() {
  const { theme } = useTheme();
  const { colors } = theme;
  const { enabled, setEnabled } = useBiometricLock();
  const { clearAll } = useEntries();
  const [authLevel, setAuthLevel] = useState<EnrolledAuthLevel | null>(null);
  const [verifying, setVerifying] = useState(false);
  const { isExporting, isImporting } = useBackupStatus();

  useEffect(() => {
    let active = true;

    getEnrolledAuthLevel().then((result) => {
      if (active) setAuthLevel(result);
    });

    return () => {
      active = false;
    };
  }, []);

  const caption = (() => {
    if (!authLevel) return "Checking device support";
    if (authLevel === "none") return "Set up biometrics or a device passcode to use the app lock.";
    if (authLevel === "passcode") return "Require your device passcode to open the app.";
    return "Require Face ID or fingerprint to open the app.";
  })();

  const handleToggle = async (value: boolean) => {
    if (!value) {
      setEnabled(false);
      analytics.capture("biometric_lock_disabled");
      return;
    }

    if (verifying || !authLevel || authLevel === "none") return;

    // Confirm with a live OS prompt (biometrics, or the device passcode on
    // passcode-only devices) before arming the lock.
    setVerifying(true);
    const confirmed = await authenticate("Enable app lock");
    setVerifying(false);

    if (confirmed) {
      setEnabled(true);
      analytics.capture("biometric_lock_enabled");
    }
  };

  const handleExport = async () => {
    if (isExporting || isImporting) return;

    // 1. Pick destination folder FIRST
    let targetDir = null;
    let useShareFallback = false;
    try {
      targetDir = await pickBackupDestinationDirectory();
      if (!targetDir) return; // User cancelled
    } catch (err) {
      logDevWarning("settings:pickExportDir", err);
      useShareFallback = true;
    }

    const controller = new AbortController();
    setExportController(controller);

    void notifyBackupProgress("Saving backup", "Preparing your backup");

    try {
      const result = await exportBackupArchive({
        signal: controller.signal,
        onProgress: (processed, total, phase) => {
          const isEntriesPhase = phase === "entries";
          const step = isEntriesPhase ? 1 : 10;
          if (processed % step !== 0 && processed !== total) return;
          const body = isEntriesPhase
            ? "Saving your entries"
            : `Saving files (${processed.toLocaleString()} of ${total.toLocaleString()})`;
          void notifyBackupProgress("Saving backup", body);
        },
      });

      if (controller.signal.aborted) return;

      if (targetDir) {
        try {
          await copyBackupToDirectory(result.fileUri, result.filename, targetDir);
        } catch (copyErr) {
          reportError("backup:copyToDirectory", copyErr);
          const isAvailable = await Sharing.isAvailableAsync();
          if (isAvailable) {
            await Sharing.shareAsync(result.fileUri, {
              mimeType: "application/octet-stream",
              UTI: "public.archive",
            });
            try {
              new File(result.fileUri).delete();
            } catch {
              // ignore
            }
          } else {
            throw copyErr;
          }
        }
      } else if (useShareFallback) {
        const isAvailable = await Sharing.isAvailableAsync();
        if (isAvailable) {
          await Sharing.shareAsync(result.fileUri, {
            mimeType: "application/octet-stream",
            UTI: "public.archive",
          });
          try {
            new File(result.fileUri).delete();
          } catch {
            // ignore
          }
        } else {
          throw new Error("No storage destination available on this device.");
        }
      }

      const entryCount = result.counts.entry;
      analytics.capture("backup_exported", {
        entry_count: entryCount,
        byte_size: result.byteSize,
      });

      void notifyBackupExportComplete(entryCount, result.byteSize);

      Alert.alert(
        "Backup saved",
        `${entryCount.toLocaleString()} ${entryCount === 1 ? "entry" : "entries"} saved.`,
        [{ text: "Done" }]
      );
    } catch (error) {
      if (controller.signal.aborted) {
        void dismissBackupProgressNotification();
        return;
      }
      const missingMedia = error instanceof MissingBackupMediaError;
      // The export already reported the missing media.
      if (!missingMedia) reportError("backup:export", error);
      analytics.capture("backup_export_failed");
      const message = missingMedia
        ? error.message
        : "Couldn’t save your backup. Check your storage and try again.";
      void notifyBackupError("Backup failed", message);
      Alert.alert("Backup failed", message);
    } finally {
      setExportController(null);
    }
  };

  const handleCancelExport = () => {
    cancelActiveBackup();
    void dismissBackupProgressNotification();
  };

  const executeImport = async (
    fileUri: string,
    counts?: ArchiveCounts,
    uncompressedBytes?: number,
    expectedArchiveBytes?: number
  ) => {
    const controller = new AbortController();
    setImportController(controller);

    void notifyBackupProgress("Importing backup", "Extracting files...");

    try {
      let lastPercent = -1;
      const result = await importBackupArchive(fileUri, {
        signal: controller.signal,
        onProgress: (processedBytes, totalBytes) => {
          const percent = totalBytes > 0 ? Math.floor((processedBytes / totalBytes) * 100) : 100;
          if (percent === lastPercent) return;
          lastPercent = percent;
          void notifyBackupProgress("Importing backup", `Extracting files (${percent}%)`);
        },
        counts,
        uncompressedBytes,
        expectedArchiveBytes,
      });

      const importedCount = result?.importedCount ?? counts?.entry ?? 0;
      let byteSize = expectedArchiveBytes;
      if (byteSize === undefined) {
        try {
          const temp = new File(fileUri);
          if (temp.exists) byteSize = temp.size;
        } catch {
          // ignore
        }
      }

      analytics.capture("backup_imported", {
        entry_count: importedCount,
        byte_size: byteSize ?? null,
      });

      void dismissBackupProgressNotification();
      void notifyBackupImportComplete(importedCount);

      Alert.alert(
        "Import complete",
        `${importedCount.toLocaleString()} ${importedCount === 1 ? "entry" : "entries"} imported.`,
        [{ text: "Done" }]
      );
    } catch (error) {
      if (controller.signal.aborted) {
        analytics.capture("backup_import_cancelled", {
          byte_size: expectedArchiveBytes ?? null,
        });
        void dismissBackupProgressNotification();
        Alert.alert("Import cancelled", "Import did not complete.");
        return;
      }
      reportError("backup:import", error);
      let byteSize = expectedArchiveBytes;
      if (byteSize === undefined) {
        try {
          const temp = new File(fileUri);
          if (temp.exists) byteSize = temp.size;
        } catch {
          // ignore
        }
      }
      analytics.capture("backup_import_failed", {
        byte_size: byteSize ?? null,
      });
      const message = IMPORT_FAILURE_MESSAGE;
      void notifyBackupError("Import failed", message);
      Alert.alert("Can’t import backup", message);
    } finally {
      setImportController(null);
      try {
        const tempFile = new File(fileUri);
        if (tempFile.exists && tempFile.uri.includes(Paths.cache.uri)) {
          tempFile.delete();
        }
      } catch (cleanupErr) {
        logDevWarning("settings:cleanupImportTemp", cleanupErr);
      }
    }
  };

  const handleImport = async () => {
    if (isImporting || isExporting) return;

    let fileUri: string | null = null;
    try {
      fileUri = await pickBackupArchiveFile();
    } catch (_error) {
      Alert.alert("Couldn’t open file", "Unable to read the selected file.");
      return;
    }

    if (!fileUri) return;

    let preview: InspectBackupResult;
    try {
      preview = await inspectBackupArchive(fileUri);
    } catch (error) {
      reportError("backup:inspect", error);
      let byteSize: number | undefined;
      try {
        const temp = new File(fileUri);
        if (temp.exists) byteSize = temp.size;
      } catch {
        // ignore
      }
      analytics.capture("backup_inspect_failed", { byte_size: byteSize ?? null });
      Alert.alert(
        "Can’t open backup",
        "This backup file appears to be corrupted or incomplete. Select a different backup file."
      );
      try {
        new File(fileUri).delete();
      } catch {
        // ignore
      }
      return;
    }

    const dateStr = new Date(preview.createdAt).toLocaleDateString(undefined, {
      dateStyle: "medium",
    });
    const entryLabel = `${preview.counts.entry.toLocaleString()} ${preview.counts.entry === 1 ? "entry" : "entries"}`;
    const startImport = () =>
      void executeImport(fileUri, preview.counts, preview.uncompressedBytes, preview.archiveBytes);
    const cancelImport = () => {
      try {
        new File(fileUri).delete();
      } catch {
        // ignore
      }
    };
    const alreadyHasContent = await hasLocalContentForImport();
    Alert.alert(
      "Import backup?",
      alreadyHasContent
        ? `${entryLabel} from ${dateStr}.\n\nImporting will permanently delete your current entries and media, then add the backup. This cannot be undone.`
        : `${entryLabel} from ${dateStr}.`,
      [
        { text: "Cancel", style: "cancel", onPress: cancelImport },
        {
          text: "Import",
          style: alreadyHasContent ? "destructive" : "default",
          onPress: startImport,
        },
      ]
    );
  };

  const handleCancelImport = () => {
    cancelActiveImport();
    void dismissBackupProgressNotification();
  };

  const confirmDeleteEntries = () =>
    confirmDestructive(
      "Delete all entries?",
      "This permanently removes every entry and its attached media. This cannot be undone.",
      "Delete",
      clearAll
    );

  return (
    <SettingsScreenScroll>
      <SettingsGroup label="SECURITY">
        <View style={styles.container}>
          <View style={styles.row}>
            <View style={styles.labelGroup}>
              <ThemedText style={[typography.settingLabel, { color: colors.text }]}>
                App Lock
              </ThemedText>
              <ThemedText style={[styles.caption, { color: colors.textSecondary }]}>
                {caption}
              </ThemedText>
            </View>
            <Switch
              value={enabled}
              onValueChange={(value) => void handleToggle(value)}
              disabled={!authLevel || authLevel === "none" || verifying}
              trackColor={{ false: colors.line, true: colors.marker }}
              thumbColor={colors.surface}
              accessibilityLabel="App lock setting"
            />
          </View>
        </View>
      </SettingsGroup>

      <SettingsGroup label="DATA BACKUP">
        <SettingsRow
          icon="upload"
          title="Export"
          subtitle={isExporting ? "Saving your backup" : "Save your timeline to a backup file"}
          badge={
            isExporting ? (
              <View style={styles.inFlightRow}>
                <ActivityIndicator size="small" color={colors.marker} />
                <Pressable
                  onPress={handleCancelExport}
                  hitSlop={8}
                  style={({ pressed }) => [styles.cancelBtn, pressed && press]}
                  accessibilityRole="button"
                  accessibilityLabel="Cancel export"
                >
                  <ThemedText
                    style={[typography.caption, { color: colors.destructive, fontWeight: "600" }]}
                  >
                    Cancel
                  </ThemedText>
                </Pressable>
              </View>
            ) : undefined
          }
          showChevron={!isExporting}
          onPress={() => {
            if (!isExporting) void handleExport();
          }}
        />

        <SettingsRow
          icon="download"
          title="Import"
          subtitle={
            isImporting ? "Importing backup" : "Replace your current timeline with a backup"
          }
          badge={
            isImporting ? (
              <View style={styles.inFlightRow}>
                <ActivityIndicator size="small" color={colors.marker} />
                <Pressable
                  onPress={handleCancelImport}
                  hitSlop={8}
                  style={({ pressed }) => [styles.cancelBtn, pressed && press]}
                  accessibilityRole="button"
                  accessibilityLabel="Cancel import"
                >
                  <ThemedText
                    style={[typography.caption, { color: colors.destructive, fontWeight: "600" }]}
                  >
                    Cancel
                  </ThemedText>
                </Pressable>
              </View>
            ) : undefined
          }
          showChevron={!isImporting}
          onPress={() => {
            if (!isImporting) void handleImport();
          }}
        />
      </SettingsGroup>

      <SettingsGroup label="STORAGE">
        <Pressable
          onPress={confirmDeleteEntries}
          style={({ pressed }) => [styles.deleteBtn, pressed && press]}
          accessibilityRole="button"
          accessibilityLabel="Delete all entries permanently"
        >
          <ThemedText style={[typography.settingLabel, { color: colors.destructive }]}>
            Delete all entries
          </ThemedText>
        </Pressable>
      </SettingsGroup>
    </SettingsScreenScroll>
  );
}

