import * as Location from "expo-location";

import type { EntryLocation } from "@/shared/types";

const MAX_ATTEMPTS = 2;
const RETRY_DELAY_MS = 1000;
const LAST_KNOWN_MAX_AGE_MS = 10 * 60 * 1000;
const LAST_KNOWN_MAX_ACCURACY_M = 2000;

export const LOCATION_UNAVAILABLE = "Not available";

// Cached for the app session; a fresh fix is only taken on refresh.
let sessionPlace: EntryLocation | null = null;

/**
 * Normalizes geocoded address components into a single canonical format:
 * "Locality, Region, Country" with consecutive and empty deduplication.
 * e.g. "Siliguri, West Bengal, India", "Austin, Texas, United States"
 */
export function formatGeocodedAddress(
  address: Location.LocationGeocodedAddress
): string | undefined {
  const getField = (val: string | null | undefined) =>
    val && val.trim().length > 0 ? val.trim() : null;

  const city = getField(address.city);
  const district = getField(address.district);
  const subregion = getField(address.subregion);
  const street = getField(address.street);
  const name = getField(address.name);
  const region = getField(address.region);
  const country = getField(address.country);

  const locality = city || district || subregion || street || name;
  const parts = [locality, region, country].filter(Boolean) as string[];
  const unique = parts.filter((part, index) => part !== parts[index - 1]);

  if (!unique.length) return undefined;
  return unique.join(", ");
}

/**
 * Returns the canonical display name for an EntryLocation.
 * Used consistently across all surfaces: Timeline, View/Reader, Details modal, Memory, etc.
 */
export function locationPlaceTitle(location?: EntryLocation | null): string {
  if (!location) return LOCATION_UNAVAILABLE;
  if (location.name?.trim()) {
    return location.name.trim();
  }
  return "Location";
}

/** Canonical coordinate string representation. */
export function formatLocationCoordinates(location: EntryLocation): string {
  return `${location.latitude.toFixed(4)}, ${location.longitude.toFixed(4)}`;
}

export function locationAccessibilityLabel(location: EntryLocation): string {
  return `${locationPlaceTitle(location)}, ${formatLocationCoordinates(location)}`;
}

async function reverseGeocode(latitude: number, longitude: number): Promise<string | undefined> {
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      const places = await Location.reverseGeocodeAsync({ latitude, longitude });
      if (places && places.length > 0 && places[0]) {
        const formatted = formatGeocodedAddress(places[0]);
        if (formatted) return formatted;
      }
    } catch {
      if (attempt < MAX_ATTEMPTS) {
        await new Promise((resolve) => setTimeout(resolve, RETRY_DELAY_MS));
      }
    }
  }
  return undefined;
}

async function coordsToPlace(latitude: number, longitude: number): Promise<EntryLocation> {
  const name = await reverseGeocode(latitude, longitude);
  return { latitude, longitude, name };
}

async function readPosition(): Promise<Location.LocationObject | null> {
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      return await Location.getCurrentPositionAsync({
        accuracy: Location.Accuracy.Balanced,
      });
    } catch {
      if (attempt < MAX_ATTEMPTS) {
        await new Promise((resolve) => setTimeout(resolve, RETRY_DELAY_MS));
      }
    }
  }

  try {
    return await Location.getLastKnownPositionAsync({
      maxAge: LAST_KNOWN_MAX_AGE_MS,
      requiredAccuracy: LAST_KNOWN_MAX_ACCURACY_M,
    });
  } catch {
    return null;
  }
}

/** The place cached for the current app session, if one was resolved already. */
export function getCachedPlace(): EntryLocation | null {
  return sessionPlace;
}

/**
 * Resolves place label from GPS on explicit user action.
 *
 * The resolved place is cached for the app session: repeat taps return it
 * instantly without another GPS fix or reverse-geocode. Pass `refresh: true`
 * to bypass the cache and take a fresh fix (which updates the cache).
 *
 * Permission determines whether the app is allowed to access location.
 * Compose determines whether the app should actually use it.
 *
 * `prompt: true` requests OS permission if not yet granted.
 */
export async function fetchPlace(
  options: { prompt?: boolean; refresh?: boolean } = {}
): Promise<EntryLocation | null> {
  const { prompt = false, refresh = false } = options;

  if (!refresh && sessionPlace) return sessionPlace;

  let permission = await Location.getForegroundPermissionsAsync();

  if (permission.status !== "granted") {
    if (!prompt) return null;
    if (permission.canAskAgain) {
      permission = await Location.requestForegroundPermissionsAsync();
    }
    if (permission.status !== "granted") return null;
  }

  const position = await readPosition();
  if (!position) return null;

  const place = await coordsToPlace(position.coords.latitude, position.coords.longitude);
  sessionPlace = place;
  return place;
}

import { useCallback, useRef, useState } from "react";
import { analytics } from "@/config/analytics";
import type { EntryLocation } from "@/shared/types";
import { fetchPlace } from "./location";

/**
 * Location attach state for the compose screen.
 *
 * `on` is the explicit user intent to attach location.
 * `place` is the resolved place data.
 * Location is strictly opt-in: no automatic fetching, no background tracking,
 * no refresh on typing. Fetches only occur when the user explicitly triggers an action.
 */
export function useLocation(initialLocation?: EntryLocation | null) {
  const [on, setOn] = useState(Boolean(initialLocation));
  const [place, setPlace] = useState<EntryLocation | null>(initialLocation ?? null);
  const [loading, setLoading] = useState(false);
  const [failed, setFailed] = useState(false);

  // Bumped on every fetch and on detach so stale responses are safely ignored.
  const fetchId = useRef(0);

  const fetchAndAttach = useCallback(
    async (options: { prompt: boolean; refresh?: boolean }) => {
      const id = ++fetchId.current;
      setLoading(true);
      setFailed(false);

      try {
        const loc = await fetchPlace(options);
        if (id !== fetchId.current) return;

        setLoading(false);
        if (loc) {
          setPlace(loc);
          setOn(true);
          setFailed(false);
          analytics.capture("location_used");
        } else {
          setFailed(true);
          if (!place) {
            setOn(false);
          }
        }
      } catch {
        if (id !== fetchId.current) return;
        setLoading(false);
        setFailed(true);
      }
    },
    [place]
  );

  const request = useCallback(async () => {
    await fetchAndAttach({ prompt: true });
  }, [fetchAndAttach]);

  const refresh = useCallback(async () => {
    await fetchAndAttach({ prompt: true, refresh: true });
  }, [fetchAndAttach]);

  const remove = useCallback(() => {
    fetchId.current += 1;
    setOn(false);
    setPlace(null);
    setFailed(false);
    setLoading(false);
  }, []);

  /** Replace the attached location with `to`, discarding edits and in-flight fetches. */
  const reset = useCallback((to: EntryLocation | null) => {
    fetchId.current += 1;
    setOn(Boolean(to));
    setPlace(to);
    setLoading(false);
    setFailed(false);
  }, []);

  const toggle = useCallback(async () => {
    if (loading) return;
    if (on) {
      remove();
    } else {
      await request();
    }
  }, [loading, on, remove, request]);

  return {
    on,
    place,
    loading,
    failed,
    request,
    refresh,
    remove,
    reset,
    toggle,
  };
}

import * as ImagePicker from "expo-image-picker";
import { useCallback, useEffect, useState } from "react";

import { analytics } from "@/config/analytics";
import { useRecording } from "@/services/audio";
import type { DraftSnapshot } from "@/services/drafts/snapshot";
import { downscaleImage, pickDocuments } from "@/services/media";
import type { Attachment, Entry } from "@/shared/types";
import { MAX_ATTACHMENTS, MAX_IMAGES } from "../types";

/**
 * Photos, voice notes, and kept documents attached to a compose draft, plus
 * the side effects that capture them (picker permissions, recorder lifecycle).
 * Isolated here so the screen's render loop stays free of media concerns.
 */
export function useMediaAttachments({
  existing,
  restored,
}: {
  existing: Entry | undefined;
  /** An unsaved draft to resume; wins over the stored entry. */
  restored: DraftSnapshot | null;
}) {
  const initial = restored ?? existing;
  const [images, setImages] = useState<string[]>(() => initial?.images ?? []);
  const [audios, setAudios] = useState<string[]>(() => initial?.audios ?? []);
  const [attachments, setAttachments] = useState<Attachment[]>(() => initial?.attachments ?? []);

  const {
    isRecording,
    durationMs: recordingDurationMs,
    liveLevels: recordingLevels,
    recordedUri,
    toggle,
    cancel,
    clear,
  } = useRecording();

  // Commit a finished take into the attachments list so the next recording
  // starts from a clean slate.
  useEffect(() => {
    if (!recordedUri || isRecording) return;
    setAudios((prev) => (prev.includes(recordedUri) ? prev : [...prev, recordedUri]));
    clear();
  }, [recordedUri, isRecording, clear]);

  const pickImage = useCallback(async () => {
    if (images.length >= MAX_IMAGES) return;

    const { granted } = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (!granted) return;

    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: "images",
      // Full quality here — downscaleImage performs the only re-encode.
      quality: 1,
      allowsMultipleSelection: true,
      selectionLimit: MAX_IMAGES - images.length,
    });
    if (!result.canceled) {
      // Shrink before state so the preview and the durable copy share one small file.
      const downscaled = await Promise.all(
        result.assets.map((asset) => downscaleImage(asset.uri, asset))
      );
      setImages((prev) => [...prev, ...downscaled]);
      analytics.capture("photo_attached", { photo_count: downscaled.length });
    }
  }, [images.length]);

  const pickAttachments = useCallback(async () => {
    if (attachments.length >= MAX_ATTACHMENTS) return;

    const picked = await pickDocuments(MAX_ATTACHMENTS - attachments.length);
    if (picked.length > 0) {
      setAttachments((prev) => [...prev, ...picked]);
      analytics.capture("file_attached", { file_count: picked.length });
    }
  }, [attachments.length]);

  const removeImage = useCallback((index: number) => {
    setImages((prev) => prev.filter((_, i) => i !== index));
  }, []);

  const removeAudio = useCallback((index: number) => {
    setAudios((prev) => prev.filter((_, i) => i !== index));
  }, []);

  const removeAttachment = useCallback((index: number) => {
    setAttachments((prev) => prev.filter((_, i) => i !== index));
  }, []);

  /** Discard edits and show the media of `to`. */
  const reset = useCallback(
    (to: Entry | undefined) => {
      // Stop the mic and drop any in-progress or finished-but-unsaved take.
      void cancel();
      setImages(to?.images ?? []);
      setAudios(to?.audios ?? []);
      setAttachments(to?.attachments ?? []);
      clear();
    },
    [cancel, clear]
  );

  return {
    images,
    audios,
    attachments,
    isRecording,
    recordingDurationMs,
    recordingLevels,
    pickImage,
    pickAttachments,
    removeImage,
    removeAudio,
    removeAttachment,
    toggleRecording: toggle,
    reset,
  };
}

import {
  requestRecordingPermissionsAsync,
  setAudioModeAsync,
  useAudioRecorder,
  useAudioRecorderState,
} from "expo-audio";
import { useCallback, useEffect, useRef, useState } from "react";
import { analytics } from "@/config/analytics";
import { RECORDING_OPTIONS, RECORDING_POLL_MS } from "./constants";
import { useAudioCoordinator } from "./usePlayback";
import { liveWaveformLevels, meteringToLevel } from "./waveform";

const MAX_LIVE_SAMPLES = 48;

export function useRecording() {
  const coordinator = useAudioCoordinator();
  const recorder = useAudioRecorder(RECORDING_OPTIONS);
  const recorderState = useAudioRecorderState(recorder, RECORDING_POLL_MS);

  const [recordedUri, setRecordedUri] = useState<string | undefined>();
  const [recordedDurationMs, setRecordedDurationMs] = useState<number | undefined>();
  const [recordedLevels, setRecordedLevels] = useState<number[]>([]);
  const [liveLevels, setLiveLevels] = useState<number[]>([]);
  const samplesRef = useRef<number[]>([]);

  useEffect(() => {
    if (!recorderState.isRecording) return;

    const level = meteringToLevel(recorderState.metering);
    samplesRef.current.push(level);
    if (samplesRef.current.length > MAX_LIVE_SAMPLES) {
      samplesRef.current.shift();
    }
    setLiveLevels([...samplesRef.current]);
  }, [recorderState.isRecording, recorderState.metering]);

  useEffect(() => {
    return () => {
      try {
        if (recorder.getStatus().isRecording) {
          void recorder.stop();
        }
      } catch {
        // Handle might already be disposed
      }
    };
  }, [recorder]);

  const start = useCallback(async (): Promise<boolean> => {
    const { granted } = await requestRecordingPermissionsAsync();
    if (!granted) return false;

    coordinator.pauseAll();
    await setAudioModeAsync({ allowsRecording: true, playsInSilentMode: true });
    setRecordedUri(undefined);
    setRecordedDurationMs(undefined);
    setRecordedLevels([]);
    samplesRef.current = [];
    setLiveLevels([]);

    await recorder.prepareToRecordAsync();
    recorder.record();
    analytics.capture("audio_recording_started");
    return true;
  }, [coordinator, recorder]);

  const stop = useCallback(async () => {
    const status = recorder.getStatus();
    const levels = liveWaveformLevels(samplesRef.current);
    await recorder.stop();
    void setAudioModeAsync({ allowsRecording: false, playsInSilentMode: true }).catch(() => {});

    if (recorder.uri) {
      setRecordedUri(recorder.uri);
      setRecordedDurationMs(status.durationMillis);
      setRecordedLevels(levels);
      analytics.capture("audio_recording_stopped", { duration_ms: status.durationMillis });
    }
  }, [recorder]);

  const toggle = useCallback(async () => {
    if (recorderState.isRecording) await stop();
    else await start();
  }, [recorderState.isRecording, start, stop]);

  const clear = useCallback(() => {
    setRecordedUri(undefined);
    setRecordedDurationMs(undefined);
    setRecordedLevels([]);
    samplesRef.current = [];
    setLiveLevels([]);
  }, []);

  /** Stop the recorder and discard the take without publishing its URI. */
  const cancel = useCallback(async () => {
    try {
      if (recorder.getStatus().isRecording) {
        await recorder.stop();
      }
    } catch {
      // Handle might already be disposed
    }
    clear();
  }, [recorder, clear]);

  const durationMs = recorderState.isRecording
    ? recorderState.durationMillis
    : (recordedDurationMs ?? 0);

  return {
    isRecording: recorderState.isRecording,
    durationMs,
    liveLevels,
    recordedUri,
    recordedDurationMs,
    recordedLevels,
    toggle,
    clear,
    cancel,
  };
}

import { Platform } from "react-native";
import { analytics } from "@/config/analytics";
import { formatBytes } from "@/shared/utils/appInfo";
import { logDevWarning } from "@/shared/utils/devLog";

type NotificationsModule = typeof import("expo-notifications");
let cachedModule: NotificationsModule | null = null;
let isHandlerConfigured = false;

function getNotifications(): NotificationsModule | null {
  if (!cachedModule) {
    try {
      cachedModule = require("expo-notifications") as NotificationsModule;
    } catch (error) {
      logDevWarning("notifications:require", error);
      return null;
    }
  }

  if (cachedModule && !isHandlerConfigured) {
    try {
      cachedModule.setNotificationHandler({
        handleNotification: async () => ({
          shouldPlaySound: true,
          shouldSetBadge: false,
          shouldShowBanner: true,
          shouldShowList: true,
        }),
      });
      isHandlerConfigured = true;
    } catch (error) {
      logDevWarning("notifications:setHandler", error);
    }
  }

  return cachedModule;
}

let channelsConfigured = false;

async function ensureBackupChannels(Notifications: NotificationsModule): Promise<void> {
  if (Platform.OS !== "android" || channelsConfigured) {
    return;
  }

  try {
    await Notifications.setNotificationChannelAsync("backup", {
      name: "Backup & Import",
      importance: Notifications.AndroidImportance.HIGH,
      vibrationPattern: [0, 250, 250, 250],
      lightColor: "#8B5CF6",
    });
    await Notifications.setNotificationChannelAsync("backup-progress", {
      name: "Backup & Import Progress",
      importance: Notifications.AndroidImportance.LOW,
      enableVibrate: false,
      sound: null,
    });
    channelsConfigured = true;
  } catch (error) {
    logDevWarning("notifications:ensureBackupChannels", error);
  }
}

/** Requests notification permission if not granted; the OS itself never re-prompts after a decision. */
export async function requestNotificationPermission(): Promise<boolean> {
  const Notifications = getNotifications();
  if (!Notifications) {
    return false;
  }

  try {
    const { status: existingStatus } = await Notifications.getPermissionsAsync();
    let finalStatus = existingStatus;

    // The OS shows the dialog only while undecided, so repeated calls never nag.
    if (existingStatus !== "granted") {
      const { status } = await Notifications.requestPermissionsAsync();
      if (existingStatus === "undetermined") {
        analytics.capture("notification_permission_prompted", {
          granted: status === "granted",
        });
      }
      finalStatus = status;
    }

    if (Platform.OS === "android") {
      await ensureBackupChannels(Notifications);
    }

    return finalStatus === "granted";
  } catch (error) {
    logDevWarning("notifications:requestPermission", error);
    return false;
  }
}

/**
 * Dispatches an immediate local notification.
 */
export async function sendLocalNotification(
  title: string,
  body: string,
  data?: Record<string, unknown>
): Promise<void> {
  const Notifications = getNotifications();
  if (!Notifications) {
    return;
  }

  try {
    await Notifications.scheduleNotificationAsync({
      content: {
        title,
        body,
        sound: true,
        data,
      },
      trigger: null,
    });
  } catch (error) {
    logDevWarning("notifications:sendLocalNotification", error);
  }
}

const BACKUP_NOTIFICATION_ID = "openlog-backup-progress";

