import * as LocalAuthentication from "expo-local-authentication";
import { Platform } from "react-native";

/** What the device can verify the owner with right now. */
export type EnrolledAuthLevel = "none" | "passcode" | "biometrics";

/**
 * The device's owner-verification level: enrolled biometrics, a passcode-only
 * screen lock, or nothing the OS could verify against. A failed probe reports
 * "none" so the lock gate opens rather than trapping the user.
 */
export async function getEnrolledAuthLevel(): Promise<EnrolledAuthLevel> {
  if (Platform.OS === "web") return "none";

  try {
    const level = await LocalAuthentication.getEnrolledLevelAsync();
    if (level === LocalAuthentication.SecurityLevel.NONE) return "none";
    if (level === LocalAuthentication.SecurityLevel.SECRET) return "passcode";
    return "biometrics";
  } catch {
    return "none";
  }
}

/**
 * Runs the OS unlock prompt: biometrics when enrolled, with the device
 * passcode as fallback, so a failed sensor read never locks the user out.
 * @see https://docs.expo.dev/versions/latest/sdk/local-authentication/
 */
export async function authenticate(reason: string): Promise<boolean> {
  if (Platform.OS === "web") return false;

  try {
    const result = await LocalAuthentication.authenticateAsync({
      promptMessage: reason,
      cancelLabel: "Cancel",
    });
    return result.success;
  } catch {
    return false;
  }
}

import * as SecureStore from "expo-secure-store";
import { useCallback, useEffect, useState } from "react";
import { Platform } from "react-native";

import { reportError } from "@/shared/utils/devLog";

/**
 * Device-bound app-lock state.
 *
 * The biometric lock is tied to this device's hardware and keychain, so it is
 * persisted in secure device-local storage instead of the settings table.
 * Backups therefore never carry the lock state to another device: each device
 * arms its own lock.
 */

const BIOMETRIC_LOCK_KEY = "applock.biometric";

type BiometricLockListener = (enabled: boolean) => void;

// Module cache keeps consumers (gate, settings screens) in sync and lets the
// lock gate mount with the correct armed state after bootstrap resolves it.
let cachedEnabled: boolean | null = null;
const listeners = new Set<BiometricLockListener>();

function publish(enabled: boolean): void {
  for (const listener of listeners) listener(enabled);
}

export async function getBiometricLockEnabled(): Promise<boolean> {
  if (cachedEnabled !== null) return cachedEnabled;
  if (Platform.OS === "web") return false;
  try {
    const value = await SecureStore.getItemAsync(BIOMETRIC_LOCK_KEY);
    cachedEnabled = value === "true";
    return cachedEnabled;
  } catch {
    return false;
  }
}

export async function setBiometricLockEnabled(value: boolean): Promise<void> {
  cachedEnabled = value;
  publish(value);
  if (Platform.OS === "web") return;
  try {
    if (value) {
      await SecureStore.setItemAsync(BIOMETRIC_LOCK_KEY, "true");
    } else {
      await SecureStore.deleteItemAsync(BIOMETRIC_LOCK_KEY);
    }
  } catch (error) {
    reportError("appLock:persist", error);
  }
}

export function subscribeBiometricLock(listener: BiometricLockListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

export interface BiometricLockSetting {
  enabled: boolean;
  setEnabled: (value: boolean) => void;
}

/** Tracks the device-bound lock state; starts synchronously once bootstrap has resolved it. */
export function useBiometricLock(): BiometricLockSetting {
  const [enabled, setEnabledState] = useState(() => cachedEnabled ?? false);

  useEffect(() => {
    let active = true;
    if (cachedEnabled === null) {
      getBiometricLockEnabled()
        .then((value) => {
          if (active) setEnabledState(value);
        })
        .catch(() => undefined);
    }
    const unsubscribe = subscribeBiometricLock((value) => {
      if (active) setEnabledState(value);
    });
    return () => {
      active = false;
      unsubscribe();
    };
  }, []);

  const setEnabled = useCallback((value: boolean) => {
    void setBiometricLockEnabled(value);
  }, []);

  return { enabled, setEnabled };
}

import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import { AppState, type AppStateStatus } from "react-native";

import { analytics } from "@/config/analytics";
import { authenticate, getEnrolledAuthLevel } from "./auth";

const UNLOCK_REASON = "Unlock your entries";
const BACKGROUND_LOCK_THRESHOLD_MS = 60 * 1000; // 1 minute in background before re-locking

const AppLockedContext = createContext(false);

export const AppLockedProvider = AppLockedContext.Provider;

/**
 * True while the app is locked. Native modals draw in their own window above the
 * lock screen, so they must stop rendering while this holds. They deliberately
 * stay up through brief inactive states: dismissing a modal there interrupts
 * anything it presented (share sheet, permission alert) and resets its content.
 */
export function useAppLocked(): boolean {
  return useContext(AppLockedContext);
}

/**
 * Owns the app-lock gate:
 *   - opens locked and prompts while the lock is enabled
 *   - hides content whenever the app is not active; this renders from JS, so
 *     the OS may take its app-switcher snapshot before the cover lands
 *   - re-locks after > 60 seconds in background
 *   - opens directly when the device has no unlock method left, so the user
 *     is never trapped outside their data (the enabled preference is kept and
 *     the lock resumes once a screen lock exists again)
 */
export function useAppLock(enabled: boolean) {
  const [locked, setLocked] = useState(enabled);
  const [prompting, setPrompting] = useState(false);
  const [appState, setAppState] = useState<AppStateStatus>(AppState.currentState);

  const lockedRef = useRef(locked);
  const promptingRef = useRef(false);
  const enabledRef = useRef(enabled);
  const backgroundTimeRef = useRef<number | null>(null);

  lockedRef.current = locked;
  enabledRef.current = enabled;

  const unlock = useCallback(async () => {
    if (promptingRef.current || !lockedRef.current) return;

    promptingRef.current = true;
    setPrompting(true);

    try {
      if ((await getEnrolledAuthLevel()) === "none") {
        // Nothing on the device can verify the owner; prompting could never
        // succeed and reinstalling would destroy the local timeline.
        analytics.capture("app_lock_bypassed");
        setLocked(false);
        return;
      }

      if (await authenticate(UNLOCK_REASON)) {
        setLocked(false);
      }
    } finally {
      promptingRef.current = false;
      setPrompting(false);
    }
  }, []);

  useEffect(() => {
    if (!enabled) {
      setLocked(false);
      return;
    }
    // Cold start prompt
    void unlock();
  }, [enabled, unlock]);

  useEffect(() => {
    const subscription = AppState.addEventListener("change", (nextState: AppStateStatus) => {
      setAppState(nextState);
      if (!enabledRef.current) return;

      if (nextState === "background") {
        backgroundTimeRef.current = Date.now();
      } else if (nextState === "active") {
        if (backgroundTimeRef.current) {
          const elapsed = Date.now() - backgroundTimeRef.current;
          backgroundTimeRef.current = null;

          if (elapsed > BACKGROUND_LOCK_THRESHOLD_MS) {
            setLocked(true);
            lockedRef.current = true;
            void unlock();
          }
        }
      }
    });

    return () => {
      subscription.remove();
    };
  }, [unlock]);

  // The re-lock decision lands in the same update as "active", so content never
  // shows for a frame between the cover lifting and the lock screen appearing.
  const contentHidden = enabled && (locked || appState === "inactive" || appState === "background");

  return { locked, contentHidden, prompting, unlock };
}

import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
import { useState } from "react";
import { analytics } from "@/config/analytics";
import { useProfile } from "@/modules/profile";
import type { RootStackParamList } from "@/navigation/types";
import { ONBOARDING_COMPLETED_KEY, setSetting } from "@/services/db/settings";
import { reportError } from "@/shared/utils";

type Navigation = NativeStackNavigationProp<RootStackParamList, "Welcome">;

export type Step = "showcase" | "name";

/** Marks onboarding done and leaves the Welcome screen. */
export function completeOnboarding(navigation: Navigation) {
  setSetting(ONBOARDING_COMPLETED_KEY, "1").catch((error) =>
    reportError("welcome:markDone", error)
  );
  if (navigation.canGoBack()) navigation.goBack();
  else navigation.replace("Timeline");
}

export function useWelcomeAuth(navigation: Navigation) {
  const { setName } = useProfile();
  const [step, setStep] = useState<Step>("showcase");
  const [name, setNameInput] = useState("");

  const finishShowcase = () => setStep("name");

  const goBackStep = () => setStep("showcase");

  const saveName = () => {
    const fullName = name.trim().replace(/\s+/g, " ");
    if (!fullName) return;
    setName(fullName);
    analytics.capture("onboarding_completed");
    completeOnboarding(navigation);
  };

  return {
    step,
    name,
    setName: setNameInput,
    canContinue: name.trim().length > 0,
    canGoBack: step === "name",
    finishShowcase,
    goBackStep,
    submitStep: step === "showcase" ? finishShowcase : saveName,
    exitToApp: () => completeOnboarding(navigation),
  };
}

