import { TAG_COLOR_IDS, type Tag, type TagColorId, type TagSummary } from "@/shared/types";
import { runDb } from "./database";

export const MAX_TAG_NAME_LENGTH = 10;
export const MAX_TAGS_PER_ENTRY = 10;

interface TagRecord {
  id: string;
  name: string;
  color_id: TagColorId;
}

/** Thrown when a rename would collide with another tag's case-insensitive key. */
export class TagNameTakenError extends Error {
  constructor() {
    super("A tag with this name already exists.");
    this.name = "TagNameTakenError";
  }
}

function createId() {
  return typeof crypto !== "undefined" && "randomUUID" in crypto
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

export function normalizeTagName(value: string): { name: string; key: string } | null {
  const name = value.normalize("NFKC").trim().replace(/\s+/g, " ");
  if (!name || [...name].length > MAX_TAG_NAME_LENGTH) return null;
  return { name, key: name.toLocaleLowerCase("en-US") };
}

function toTag(row: TagRecord): Tag {
  return { id: row.id, name: row.name, colorId: row.color_id };
}

export async function getTags(): Promise<Tag[]> {
  return runDb(async (db) => {
    const rows = await db.getAllAsync<TagRecord>(
      "SELECT id, name, color_id FROM tags ORDER BY name COLLATE NOCASE, id"
    );
    return rows.map(toTag);
  });
}

export async function getTag(id: string): Promise<Tag | null> {
  return runDb(async (db) => {
    const row = await db.getFirstAsync<TagRecord>(
      "SELECT id, name, color_id FROM tags WHERE id = ?",
      id
    );
    return row ? toTag(row) : null;
  });
}

/** Every tag, alphabetical, with the number of entries carrying it (unused tags included). */
export async function getTagSummaries(): Promise<TagSummary[]> {
  return runDb(async (db) => {
    const rows = await db.getAllAsync<TagRecord & { entry_count: number }>(
      `SELECT t.id, t.name, t.color_id, COUNT(et.entry_id) AS entry_count
         FROM tags t
         LEFT JOIN entry_tags et ON et.tag_id = t.id
        GROUP BY t.id
        ORDER BY t.name COLLATE NOCASE, t.id`
    );
    return rows.map((row) => ({ ...toTag(row), entryCount: row.entry_count }));
  });
}

export async function createTag(input: { name: string; colorId: TagColorId }): Promise<Tag> {
  const normalized = normalizeTagName(input.name);
  if (!normalized) throw new Error(`Tags must be between 1 and ${MAX_TAG_NAME_LENGTH} characters.`);
  if (!TAG_COLOR_IDS.includes(input.colorId)) throw new Error("Invalid tag color.");

  return runDb(async (db) => {
    const existing = await db.getFirstAsync<TagRecord>(
      "SELECT id, name, color_id FROM tags WHERE key = ?",
      normalized.key
    );
    if (existing) return toTag(existing);

    const tag = { id: createId(), name: normalized.name, colorId: input.colorId };
    const now = Date.now();
    await db.runAsync(
      "INSERT INTO tags (id, name, key, color_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?)",
      [tag.id, tag.name, normalized.key, tag.colorId, now, now]
    );
    return tag;
  });
}

export async function updateTag(
  id: string,
  input: { name: string; colorId: TagColorId }
): Promise<Tag> {
  const normalized = normalizeTagName(input.name);
  if (!normalized) throw new Error(`Tags must be between 1 and ${MAX_TAG_NAME_LENGTH} characters.`);
  if (!TAG_COLOR_IDS.includes(input.colorId)) throw new Error("Invalid tag color.");

  return runDb(async (db) => {
    const duplicate = await db.getFirstAsync<{ id: string }>(
      "SELECT id FROM tags WHERE key = ? AND id <> ?",
      normalized.key,
      id
    );
    if (duplicate) throw new TagNameTakenError();

    await db.runAsync(
      "UPDATE tags SET name = ?, key = ?, color_id = ?, updated_at = ? WHERE id = ?",
      [normalized.name, normalized.key, input.colorId, Date.now(), id]
    );
    const row = await db.getFirstAsync<TagRecord>(
      "SELECT id, name, color_id FROM tags WHERE id = ?",
      id
    );
    if (!row) throw new Error("Tag not found");
    return toTag(row);
  });
}

export async function deleteTag(id: string): Promise<void> {
  await runDb(async (db) => {
    await db.runAsync("DELETE FROM tags WHERE id = ?", id);
  });
}

import type { Attachment, EntryLocation, Tag } from "@/shared/types";

/** Unsaved compose content. Media fields hold live file URIs. */
export interface DraftSnapshot {
  text: string;
  images: string[];
  audios: string[];
  attachments: Attachment[];
  tags: Tag[];
  createdAt: number;
  location: EntryLocation | null;
}

const DRAFT_FORMAT_VERSION = 1;

/**
 * Bounds a restored list so a damaged draft file cannot flood the compose screen.
 * Looser than the compose limits on purpose; those apply when adding media.
 */
const MAX_DRAFT_ITEMS = 50;

// Draft slots are named "new" or by entry id; nothing that could escape the drafts directory.
const KEY_PATTERN = "[A-Za-z0-9-]{1,64}";
const DRAFT_KEY = new RegExp(`^${KEY_PATTERN}$`);
const FILE_REF = new RegExp(`^(media|drafts/${KEY_PATTERN})/[A-Za-z0-9][A-Za-z0-9._-]{0,127}$`);

export function isDraftKey(key: string): boolean {
  return DRAFT_KEY.test(key);
}

/**
 * A stored file reference: a path relative to the document directory, either
 * entry media ("media/<file>") or a draft-owned copy ("drafts/<key>/<file>").
 */
export function isDraftFileRef(ref: string): boolean {
  return FILE_REF.test(ref);
}

/** Stable comparison key: two drafts with the same signature store the same content. */
export function draftSignature(draft: DraftSnapshot): string {
  return JSON.stringify([
    draft.text,
    draft.images,
    draft.audios,
    draft.attachments.map((attachment) => [attachment.uri, attachment.name]),
    draft.tags.map((tag) => tag.id),
    draft.createdAt,
    draft.location
      ? [draft.location.latitude, draft.location.longitude, draft.location.name ?? null]
      : null,
  ]);
}

/** Serializes a draft whose media fields already hold file refs. */
export function serializeDraftSnapshot(draft: DraftSnapshot): string {
  return JSON.stringify({ version: DRAFT_FORMAT_VERSION, ...draft });
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseRefs(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value
    .filter((ref): ref is string => typeof ref === "string" && isDraftFileRef(ref))
    .slice(0, MAX_DRAFT_ITEMS);
}

function parseAttachments(value: unknown): Attachment[] {
  if (!Array.isArray(value)) return [];
  return value
    .filter(isRecord)
    .filter((item) => typeof item.uri === "string" && isDraftFileRef(item.uri))
    .slice(0, MAX_DRAFT_ITEMS)
    .map((item) => ({
      uri: item.uri as string,
      name: typeof item.name === "string" && item.name ? item.name : "File",
      mime: typeof item.mime === "string" ? item.mime : undefined,
      size: typeof item.size === "number" ? item.size : undefined,
    }));
}

function parseTags(value: unknown): Tag[] {
  if (!Array.isArray(value)) return [];
  return value
    .filter(isRecord)
    .filter(
      (item) =>
        typeof item.id === "string" &&
        typeof item.name === "string" &&
        typeof item.colorId === "string"
    )
    .slice(0, MAX_DRAFT_ITEMS)
    .map((item) => ({
      id: item.id as string,
      name: item.name as string,
      colorId: item.colorId as Tag["colorId"],
    }));
}

function parseLocation(value: unknown): EntryLocation | null {
  if (!isRecord(value)) return null;
  const { latitude, longitude, name } = value;
  if (typeof latitude !== "number" || !Number.isFinite(latitude)) return null;
  if (typeof longitude !== "number" || !Number.isFinite(longitude)) return null;
  return typeof name === "string" ? { latitude, longitude, name } : { latitude, longitude };
}

/**
 * Parses a stored draft whose media fields hold file refs. Unknown versions
 * and malformed files yield `null`; malformed fields are dropped individually.
 * Tag colors are refreshed from the database on restore.
 */
export function parseDraftSnapshot(json: string): DraftSnapshot | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(json);
  } catch {
    return null;
  }
  if (!isRecord(parsed) || parsed.version !== DRAFT_FORMAT_VERSION) return null;
  if (typeof parsed.createdAt !== "number" || !Number.isFinite(parsed.createdAt)) return null;

  return {
    text: typeof parsed.text === "string" ? parsed.text : "",
    images: parseRefs(parsed.images),
    audios: parseRefs(parsed.audios),
    attachments: parseAttachments(parsed.attachments),
    tags: parseTags(parsed.tags),
    createdAt: parsed.createdAt,
    location: parseLocation(parsed.location),
  };
}

import { Directory, File, Paths } from "expo-file-system";

import { fileExtension } from "@/services/media/attachments";
import { createMediaFilename } from "@/services/media/storage";
import type { Attachment } from "@/shared/types";
import { reportError } from "@/shared/utils/devLog";
import {
  type DraftSnapshot,
  isDraftFileRef,
  isDraftKey,
  parseDraftSnapshot,
  serializeDraftSnapshot,
} from "./snapshot";

/** Draft slot for an entry that has not been saved yet; edits use the entry id. */
export const NEW_ENTRY_DRAFT = "new";

const DRAFT_FILE = "draft.json";
// Written first and renamed over DRAFT_FILE, so a crash mid-write keeps the previous draft.
const PENDING_FILE = "draft.pending.json";
const MAX_DRAFT_BYTES = 4 * 1024 * 1024;

// Picker, recorder, and image-manipulator URIs point into the OS cache, which may be
// purged after the app dies, so a draft keeps its own copy of each such file. This
// remembers which copy belongs to which source so autosave copies a file only once.
const copiesByKey = new Map<string, Map<string, string>>();

// One operation at a time per draft, so a slow write cannot land after the discard
// that followed it, while a large copy for one draft never delays opening another.
// Discarding every draft waits for, and blocks, all of them.
const queues = new Map<string, Promise<unknown>>();
let barrier: Promise<unknown> = Promise.resolve();

function enqueue<T>(key: string, task: () => Promise<T>): Promise<T> {
  const run = Promise.all([queues.get(key), barrier]).then(task);
  queues.set(
    key,
    run.catch(() => undefined)
  );
  return run;
}

function draftsDirectory(): Directory {
  return new Directory(Paths.document, "drafts");
}

function draftDirectory(key: string): Directory {
  if (!isDraftKey(key)) throw new Error("Invalid draft key.");
  return new Directory(draftsDirectory(), key);
}

function documentPrefix(): string {
  const uri = Paths.document.uri;
  return uri.endsWith("/") ? uri : `${uri}/`;
}

/**
 * Returns the stored ref for a live URI, copying files from outside the
 * document directory, or `null` when the file can no longer be copied.
 */
async function toFileRef(options: {
  key: string;
  dir: Directory;
  uri: string;
  copies: Map<string, string>;
}): Promise<string | null> {
  const { key, dir, uri, copies } = options;
  const prefix = documentPrefix();
  if (uri.startsWith(prefix)) {
    const ref = uri.slice(prefix.length);
    if (isDraftFileRef(ref)) return ref;
  }

  const copied = copies.get(uri);
  if (copied && new File(dir, copied).exists) return `drafts/${key}/${copied}`;

  // The saved entry derives its own extension, so the source basename is enough here.
  const filename = createMediaFilename(fileExtension(uri.split("?")[0].split("/").pop() ?? ""));
  const target = new File(dir, filename);
  try {
    await new File(uri).copy(target);
  } catch (error) {
    // A purged cache file must not cost the rest of the draft.
    reportError("drafts:copyFile", error);
    if (target.exists) target.delete();
    return null;
  }
  copies.set(uri, filename);
  return `drafts/${key}/${filename}`;
}

/** Resolves a stored ref to a live URI, or `null` when its file is gone. */
function fromFileRef(ref: string): string | null {
  const file = new File(Paths.document, ref);
  return file.exists ? file.uri : null;
}

/** Deletes draft-owned copies the latest draft no longer references. */
function pruneCopies(options: { key: string; dir: Directory; refs: Set<string> }): void {
  const { key, dir, refs } = options;
  for (const item of dir.list()) {
    if (!(item instanceof File) || item.name === DRAFT_FILE || item.name === PENDING_FILE) continue;
    if (!refs.has(`drafts/${key}/${item.name}`)) item.delete();
  }
  const copies = copiesByKey.get(key);
  if (!copies) return;
  for (const [source, filename] of copies) {
    if (!refs.has(`drafts/${key}/${filename}`)) copies.delete(source);
  }
}

/** Writes the draft for `key`, replacing any earlier one. */
export function writeDraft(key: string, draft: DraftSnapshot): Promise<void> {
  return enqueue(key, async () => {
    const dir = draftDirectory(key);
    dir.create({ idempotent: true, intermediates: true });
    const copies = copiesByKey.get(key) ?? new Map<string, string>();
    copiesByKey.set(key, copies);

    const ref = (uri: string) => toFileRef({ key, dir, uri, copies });
    const refs = async (uris: string[]) =>
      (await Promise.all(uris.map(ref))).filter((uri): uri is string => uri !== null);
    const images = await refs(draft.images);
    const audios = await refs(draft.audios);
    const attachments: Attachment[] = [];
    for (const attachment of draft.attachments) {
      const uri = await ref(attachment.uri);
      if (uri) attachments.push({ ...attachment, uri });
    }

    const pending = new File(dir, PENDING_FILE);
    pending.write(serializeDraftSnapshot({ ...draft, images, audios, attachments }));
    pending.moveSync(new File(dir, DRAFT_FILE), { overwrite: true });

    pruneCopies({
      key,
      dir,
      refs: new Set([...images, ...audios, ...attachments.map((attachment) => attachment.uri)]),
    });
  });
}

/**
 * Reads the draft for `key` with media resolved to live URIs. Files that have
 * since disappeared are dropped; an unreadable draft reads as none.
 */
export function loadDraft(key: string): Promise<DraftSnapshot | null> {
  return enqueue(key, async () => {
    const dir = draftDirectory(key);
    if (!dir.exists) return null;

    // A complete pending file is newer than DRAFT_FILE; a torn one fails to parse.
    for (const name of [PENDING_FILE, DRAFT_FILE]) {
      const file = new File(dir, name);
      if (!file.exists || file.size > MAX_DRAFT_BYTES) continue;
      const stored = parseDraftSnapshot(await file.text());
      if (!stored) continue;

      const resolve = (refs: string[]) =>
        refs.flatMap((ref) => {
          const uri = fromFileRef(ref);
          return uri ? [uri] : [];
        });
      return {
        ...stored,
        images: resolve(stored.images),
        audios: resolve(stored.audios),
        attachments: stored.attachments.flatMap((attachment) => {
          const uri = fromFileRef(attachment.uri);
          return uri ? [{ ...attachment, uri }] : [];
        }),
      };
    }
    return null;
  });
}

/** Removes the draft for `key` and every file only it owned. */
export function discardDraft(key: string): Promise<void> {
  return enqueue(key, async () => {
    copiesByKey.delete(key);
    const dir = draftDirectory(key);
    if (dir.exists) dir.delete();
  });
}

/** Removes every stored draft, e.g. when all entries are deleted. */
export function discardAllDrafts(): Promise<void> {
  const run = Promise.all([...queues.values(), barrier]).then(() => {
    copiesByKey.clear();
    const dir = draftsDirectory();
    if (dir.exists) dir.delete();
  });
  barrier = run.catch(() => undefined);
  return run;
}

import { createContext, type ReactNode, useCallback, useContext, useMemo, useState } from "react";

import { setUserName as persistUserName } from "@/services/db/settings";
import { useDebouncedCallback } from "@/shared/hooks/useDebouncedCallback";
import { reportError } from "@/shared/utils/devLog";

interface ProfileContextValue {
  name: string | null;
  setName: (name: string) => void;
}

const ProfileContext = createContext<ProfileContextValue>({
  name: null,
  setName: () => {},
});

interface ProfileProviderProps {
  children: ReactNode;
  initialName: string | null;
}

export function ProfileProvider({ children, initialName }: ProfileProviderProps) {
  const [name, setNameState] = useState<string | null>(initialName);

  const debouncedPersist = useDebouncedCallback((next: string) => {
    void persistUserName(next).catch((error) => {
      reportError("profile:persistName", error);
    });
  }, 400);

  const setName = useCallback(
    (next: string) => {
      setNameState(next || null);
      debouncedPersist(next);
    },
    [debouncedPersist]
  );

  const value = useMemo(() => ({ name, setName }), [name, setName]);

  return <ProfileContext.Provider value={value}>{children}</ProfileContext.Provider>;
}

export function useProfile() {
  return useContext(ProfileContext);
}

export interface EntryLocation {
  latitude: number;
  longitude: number;
  /** City or town, state, country — e.g. "Austin, Texas, United States". */
  name?: string;
}

/** A generic attached document (PDF, spreadsheet, video, anything) kept alongside an entry. */
export interface Attachment {
  /** Media reference: the stored filename on inputs, resolved to a live file URI on read. */
  uri: string;
  /** Original filename shown to the user, e.g. "Invoice.pdf". */
  name: string;
  mime?: string;
  size?: number;
}

export const TAG_COLOR_IDS = ["clay", "amber", "sage", "violet", "teal", "rose"] as const;
export type TagColorId = (typeof TAG_COLOR_IDS)[number];

export interface Tag {
  id: string;
  name: string;
  colorId: TagColorId;
}

/** A tag with how many entries carry it, for browsing and choosing tags. */
export interface TagSummary extends Tag {
  entryCount: number;
}

export interface Entry {
  id: string;
  createdAt: number;
  updatedAt: number;
  text?: string;
  /** Live file URIs resolved from stored filenames; SQLite persists bare filenames only. */
  images: string[];
  audios: string[];
  attachments: Attachment[];
  tags: Tag[];
  location?: EntryLocation;
}

export interface NewEntryInput {
  text?: string | null;
  images?: string[];
  audios?: string[];
  attachments?: Attachment[];
  tagIds?: string[];
  createdAt?: number;
  location?: EntryLocation | null;
}

export interface UpdateEntryInput {
  /** `undefined` keeps the stored text; `null` clears it. */
  text?: string | null;
  images?: string[];
  audios?: string[];
  attachments?: Attachment[];
  tagIds?: string[];
  createdAt?: number;
  location?: EntryLocation | null;
}

export interface EntrySearchResult {
  entry: Entry;
  /** Context around the first text match; empty when the entry has no text. Match ranges are wrapped in `\u0001 … \u0002` markers. */
  snippet: string;
  /** Context around a location-name match; empty when the entry has no location. Same marker convention. */
  locationSnippet: string;
}

import {
  SourceSans3_400Regular,
  SourceSans3_500Medium,
  SourceSans3_600SemiBold,
  useFonts,
} from "@expo-google-fonts/source-sans-3";
import { useEffect, useState } from "react";
import { useColorScheme } from "react-native";
import { getBiometricLockEnabled } from "@/services/auth";
import { getAllUserPreferences } from "@/services/db/settings";
import { fontManager } from "@/services/fonts";
import { logDevWarning, reportError } from "@/shared/utils/devLog";
import { DEFAULT_PREFERENCES, resolveTheme, resolveThemeMode, type UserPreferences } from "@/theme";

export interface AppBootstrapState {
  ready: boolean;
  preferences: UserPreferences;
  resolvedMode: "light" | "dark";
  backgroundColor: string;
  userName: string | null;
  onboardingCompleted: boolean;
  /** The database could not be opened; nothing that reads or writes it may mount. */
  databaseUnavailable: boolean;
}

/** Loads fonts, preferences, profile, and the device-bound lock state before the first interactive screen. */
export function useAppBootstrap(): AppBootstrapState {
  const systemScheme = useColorScheme();
  const [preferences, setPreferences] = useState<UserPreferences | null>(null);
  const [userName, setUserName] = useState<string | null>(null);
  const [onboardingCompleted, setOnboardingCompleted] = useState(false);
  const [profileLoaded, setProfileLoaded] = useState(false);
  const [databaseUnavailable, setDatabaseUnavailable] = useState(false);
  const [fontsLoaded, fontError] = useFonts({
    SourceSans3_400Regular,
    SourceSans3_500Medium,
    SourceSans3_600SemiBold,
    "BricolageGrotesque-Bold": require("../../../assets/fonts/BricolageGrotesque-Bold.ttf"),
  });

  useEffect(() => {
    let active = true;

    // The device-bound lock resolves here so the lock gate mounts with the correct armed state.
    const loadPreferences = () =>
      Promise.all([getAllUserPreferences(), getBiometricLockEnabled()])
        .then(async ([data]) => {
          if (!active) return;
          setUserName(data.userName);
          setOnboardingCompleted(data.onboardingCompleted);
          setPreferences(data.preferences);

          const selectedFont = data.preferences.appearance.fontFamily;
          if (selectedFont && selectedFont !== "Source Sans 3") {
            // Bounded load attempt on startup so app boots quickly even if offline or slow
            try {
              await Promise.race([
                fontManager.load(selectedFont),
                new Promise((resolve) => setTimeout(resolve, 2000)),
              ]);
            } catch (error) {
              logDevWarning("bootstrap:fontLoad", error);
            }
          }
        })
        .catch((error) => {
          reportError("bootstrap:loadPreferences", error);
          if (active) {
            setPreferences(DEFAULT_PREFERENCES);
            setDatabaseUnavailable(true);
          }
        })
        .finally(() => {
          if (active) setProfileLoaded(true);
        });

    void loadPreferences();

    return () => {
      active = false;
    };
  }, []);

  const effectivePreferences = preferences ?? DEFAULT_PREFERENCES;
  const resolvedMode = resolveThemeMode(effectivePreferences.appearance.mode, systemScheme);
  const theme = resolveTheme(effectivePreferences, systemScheme);
  const backgroundColor = theme.colors.background;
  const fontsReady = fontsLoaded || Boolean(fontError);
  // Splash hides from App's BootstrapGate once local bootstrap finishes.
  const ready = fontsReady && profileLoaded && preferences !== null;

  return {
    ready,
    preferences: effectivePreferences,
    resolvedMode,
    backgroundColor,
    userName,
    onboardingCompleted,
    databaseUnavailable,
  };
}

import type { SchemaDatabase } from "../schema.ts";

/** The complete fresh-install schema. Keep this file unchanged after it ships. */
export async function migrateToV1(db: SchemaDatabase, _schema: string): Promise<void> {
  await db.execAsync(`
    CREATE TABLE entries (
      id          TEXT PRIMARY KEY NOT NULL,
      created_at  INTEGER NOT NULL,
      updated_at  INTEGER NOT NULL,
      text        TEXT,
      images      TEXT,
      audios      TEXT,
      attachments TEXT,
      latitude    REAL,
      longitude   REAL,
      location    TEXT
    );
    CREATE INDEX idx_entries_created_at_id
      ON entries (created_at DESC, id DESC);
    CREATE TABLE tags (
      id         TEXT PRIMARY KEY NOT NULL,
      name       TEXT NOT NULL,
      key        TEXT NOT NULL UNIQUE,
      color_id   TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );
    CREATE TABLE entry_tags (
      entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE,
      tag_id   TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
      PRIMARY KEY (entry_id, tag_id)
    );
    CREATE INDEX idx_entry_tags_tag_entry
      ON entry_tags (tag_id, entry_id);
    CREATE TABLE settings (
      key   TEXT PRIMARY KEY NOT NULL,
      value TEXT NOT NULL
    );
  `);
}

import { Directory, File, Paths } from "expo-file-system";

import {
  backupGateGeneration,
  waitForBackupGates,
  waitForImportGate,
} from "@/services/backup/utils";
import { reportError } from "@/shared/utils/devLog";

/** The app's single durable media directory; the database stores bare filenames relative to it. */
export function mediaDirectory(): Directory {
  return new Directory(Paths.document, "media");
}

/** Resolves a stored media filename (e.g. "uuid.jpg") to its live file URI for display and playback. */
export function mediaFileUri(filename: string): string {
  return new File(mediaDirectory(), filename).uri;
}

/** Generates a collision-free filename for durable media storage. */
export function createMediaFilename(ext: string): string {
  const cleanExt = ext.replace(/^\./, "").toLowerCase() || "bin";
  const uuid =
    typeof crypto !== "undefined" && "randomUUID" in crypto
      ? crypto.randomUUID()
      : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
  return `${uuid}.${cleanExt}`;
}

const COPY_ATTEMPTS = 3;

// Copies whose save has not settled. Cleanup skips them until `releaseMediaCopies`: a committed
// row then protects the file, and a failed save's copy is an orphan any cleanup may delete.
const uncommittedCopies = new Set<string>();

/**
 * Copies a picked or recorded file into the durable media directory and returns
 * its stored filename. Cache and picker URIs are ephemeral, so only durable
 * copies may be referenced by an entry. A source already inside the media
 * directory passes through unchanged — re-editing an entry must not duplicate
 * its files.
 */
export async function persistMedia(sourceUri: string, ext: string): Promise<string> {
  await waitForImportGate();
  const dir = mediaDirectory();
  dir.create({ idempotent: true, intermediates: true });

  const dirPrefix = dir.uri.endsWith("/") ? dir.uri : `${dir.uri}/`;
  if (sourceUri.startsWith(dirPrefix)) {
    return sourceUri.slice(dirPrefix.length);
  }

  const filename = createMediaFilename(ext);
  uncommittedCopies.add(filename);
  const target = new File(dir, filename);
  for (let attempt = 1; attempt <= COPY_ATTEMPTS; attempt++) {
    const generation = backupGateGeneration();
    try {
      dir.create({ idempotent: true, intermediates: true });
      await new File(sourceUri).copy(target);
    } catch (error) {
      if (target.exists) target.delete();
      // Only a backup that started meanwhile, such as a restore pruning the copy, earns a retry.
      if (attempt === COPY_ATTEMPTS || generation === backupGateGeneration()) {
        uncommittedCopies.delete(filename);
        throw error;
      }
    }
    // A restore that began during the copy prunes files its timeline does not reference.
    await waitForImportGate();
    if (target.exists) return filename;
  }
  uncommittedCopies.delete(filename);
  throw new Error("The media file could not be saved.");
}

/** Thrown when a save references a media file that is not on disk. The UI shows the message. */
export class MissingMediaError extends Error {}

/**
 * Waits out a running restore, then rejects if a media file of the entry is missing. The save
 * must not commit a reference to a file that does not exist. Call it right before the entry's
 * database write: that write is then queued ahead of any later restore's replacement, so the
 * restore either keeps the file or replaces the entry.
 */
export async function assertMediaPresent(filenames: readonly string[]): Promise<void> {
  await waitForImportGate();
  const dir = mediaDirectory();
  for (const filename of filenames) {
    if (!new File(dir, filename).exists) {
      throw new MissingMediaError(
        "Media in this entry is missing. Remove it or add it again, then save."
      );
    }
  }
}

/** Call once the save that references these files has committed or failed. */
export function releaseMediaCopies(filenames: readonly string[]): void {
  for (const filename of filenames) uncommittedCopies.delete(filename);
}

function listMediaFiles(): string[] {
  const dir = mediaDirectory();
  if (!dir.exists) return [];
  return dir
    .list()
    .filter((item) => item instanceof File)
    .map((item) => item.name);
}

interface DeleteMediaFilesInput {
  /** Picks the filenames to delete; it may run more than once and must read current state. */
  select: () => Promise<readonly string[]>;
}

/**
 * Deletes the stored media files `select` names. `select` runs and the files are deleted
 * while no export reads or import replaces media; if one starts in between, `select` runs again.
 * Missing files are ignored.
 */
export async function deleteMediaFiles({ select }: DeleteMediaFilesInput): Promise<void> {
  for (;;) {
    const generation = await waitForBackupGates();
    const filenames = await select();
    if (generation !== backupGateGeneration()) continue;

    // Synchronous deletes keep a backup from starting between the check above and the last delete.
    const dir = mediaDirectory();
    for (const filename of filenames) {
      try {
        const file = new File(dir, filename);
        if (file.exists) file.delete();
      } catch (error) {
        reportError("media:deleteFiles", error);
      }
    }
    return;
  }
}

/**
 * Deletes stored media that `filterUnreferenced` reports no entry uses, such as files left by an
 * interrupted save or restore. Uncommitted copies are kept: their save may still be running.
 * They are listed before `filterUnreferenced` reads the database, so a copy whose entry commits
 * in between is either still skipped here or already referenced there.
 */
export function deleteUnreferencedMedia(
  filterUnreferenced: (filenames: string[]) => Promise<string[]>
): Promise<void> {
  return deleteMediaFiles({
    select: async () => {
      const candidates = listMediaFiles().filter((filename) => !uncommittedCopies.has(filename));
      return candidates.length > 0 ? filterUnreferenced(candidates) : [];
    },
  });
}

import * as DocumentPicker from "expo-document-picker";
import { Alert } from "react-native";
import { open } from "react-native-file-viewer-turbo";

import type { Attachment } from "@/shared/types";
import { logDevWarning } from "@/shared/utils/devLog";
import { persistMedia } from "./storage";

/** Derives a safe extension from a filename or mime type; `bin` as the last resort. */
export function fileExtension(name: string, mime?: string): string {
  const ext = name.includes(".") ? (name.split(".").pop() ?? "") : "";
  if (ext && /^[a-zA-Z0-9]{1,8}$/.test(ext)) return ext.toLowerCase();
  const mimeExt = mime?.split("/").pop();
  if (mimeExt && /^[a-zA-Z0-9]{1,8}$/.test(mimeExt)) return mimeExt.toLowerCase();
  return "bin";
}

/**
 * Opens the system document picker for any file type and copies each selection
 * into cache. URIs remain ephemeral until the draft is saved.
 */
export async function pickDocuments(maxCount: number): Promise<Attachment[]> {
  if (maxCount <= 0) return [];

  const result = await DocumentPicker.getDocumentAsync({
    type: "*/*",
    multiple: true,
    copyToCacheDirectory: true,
  });
  if (result.canceled) return [];

  const picked = result.assets.slice(0, maxCount);
  const attachments: Attachment[] = [];

  for (const asset of picked) {
    attachments.push({
      uri: asset.uri,
      name: asset.name || "File",
      mime: asset.mimeType,
      size: asset.size,
    });
  }

  return attachments;
}

/**
 * Copies a picked attachment into the durable media directory; its stored
 * filename replaces the ephemeral picker URI.
 */
export async function persistAttachment(attachment: Attachment): Promise<Attachment> {
  const ext = fileExtension(attachment.name, attachment.mime);
  return { ...attachment, uri: await persistMedia(attachment.uri, ext) };
}

/** Opens a kept file in the device's supported document viewer. */
export async function openAttachment(file: Attachment): Promise<void> {
  try {
    await open(file.uri, {
      displayName: file.name,
      showOpenWithDialog: true,
      showAppsSuggestions: true,
    });
  } catch (error) {
    logDevWarning("attachments:openAttachment", error);
    Alert.alert(
      "Could not open file",
      "Install or enable an app that supports this file type, then try again."
    );
  }
}

/** Human-readable byte size for attachment chips, e.g. "1.4 MB". */
export function formatAttachmentSize(bytes?: number): string | undefined {
  if (!bytes || bytes <= 0) return undefined;
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`;
}

import { ImageManipulator, SaveFormat } from "expo-image-manipulator";

import { reportError } from "@/shared/utils/devLog";

/** Longest allowed edge for stored photos — raw camera resolution would bloat storage. */
export const IMAGE_MAX_DIMENSION = 1920;

/** JPEG quality used when re-encoding stored photos. */
export const IMAGE_JPEG_QUALITY = 0.8;

/**
 * Downscale a photo so its longest edge fits IMAGE_MAX_DIMENSION, re-encoded as JPEG.
 * Images already within bounds (and any failure) return the original URI.
 */
export async function downscaleImage(
  uri: string,
  knownDimensions?: { width?: number | null; height?: number | null }
): Promise<string> {
  try {
    let { width, height } = knownDimensions ?? {};

    // Picker assets carry dimensions; probe only when missing.
    if (!width || !height) {
      const probe = await ImageManipulator.manipulate(uri).renderAsync();
      width = probe.width;
      height = probe.height;
    }

    const longestEdge = Math.max(width ?? 0, height ?? 0);
    if (!longestEdge || longestEdge <= IMAGE_MAX_DIMENSION) {
      return uri;
    }

    // Resize by the longest edge; the other dimension keeps its ratio.
    const resize =
      (width ?? 0) >= (height ?? 0)
        ? { width: IMAGE_MAX_DIMENSION }
        : { height: IMAGE_MAX_DIMENSION };

    const rendered = await ImageManipulator.manipulate(uri).resize(resize).renderAsync();
    const saved = await rendered.saveAsync({
      compress: IMAGE_JPEG_QUALITY,
      format: SaveFormat.JPEG,
    });
    return saved.uri;
  } catch (error) {
    reportError("media:downscaleImage", error);
    return uri;
  }
}

import * as Sharing from "expo-sharing";
import { Alert } from "react-native";

import { reportError } from "@/shared/utils/devLog";

function mimeTypeForUri(uri: string): string {
  const lower = uri.split("?")[0].toLowerCase();
  if (lower.endsWith(".png")) return "image/png";
  if (lower.endsWith(".webp")) return "image/webp";
  if (lower.endsWith(".heic")) return "image/heic";
  if (lower.endsWith(".heif")) return "image/heif";
  if (lower.endsWith(".gif")) return "image/gif";
  if (lower.endsWith(".avif")) return "image/avif";
  if (lower.endsWith(".bmp")) return "image/bmp";
  if (lower.endsWith(".tif") || lower.endsWith(".tiff")) return "image/tiff";
  return "image/jpeg";
}

/** Opens the native share sheet for a local image file. */
export async function shareImage(uri: string): Promise<void> {
  try {
    const available = await Sharing.isAvailableAsync();
    if (!available) {
      Alert.alert("Sharing unavailable", "This device cannot share photos right now.");
      return;
    }

    await Sharing.shareAsync(uri, { mimeType: mimeTypeForUri(uri) });
  } catch (error) {
    reportError("media:shareImage", error);
    Alert.alert("Could not share", "Try again.");
  }
}

import type { Attachment } from "@/shared/types";

export function parseUris(json: string | null | undefined): string[] {
  if (!json) return [];
  try {
    const parsed = JSON.parse(json) as unknown;
    if (Array.isArray(parsed)) {
      return parsed.filter((uri): uri is string => typeof uri === "string");
    }
    return [];
  } catch {
    return [];
  }
}

/** Parses a stored `attachments` column, tolerating malformed rows from older or corrupted data. */
export function parseAttachments(json: string | null | undefined): Attachment[] {
  if (!json) return [];
  try {
    const parsed = JSON.parse(json) as unknown;
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((item): item is Record<string, unknown> => typeof item === "object" && item !== null)
      .map((item) => ({
        uri: typeof item.uri === "string" ? item.uri : "",
        name: typeof item.name === "string" && item.name ? item.name : "File",
        // Restores before the archive field was mapped stored it as `mimeType`.
        mime:
          typeof item.mime === "string"
            ? item.mime
            : typeof item.mimeType === "string"
              ? item.mimeType
              : undefined,
        size: typeof item.size === "number" ? item.size : undefined,
      }))
      .filter((attachment) => attachment.uri.length > 0);
  } catch {
    return [];
  }
}

/**
 * Media URI parsing and filename extraction utilities.
 */
export function extractMediaFilenameFromUri(rawUri: string): string | null {
  if (!rawUri || typeof rawUri !== "string") return null;
  if (rawUri.startsWith("http://") || rawUri.startsWith("https://")) return null;
  let path = rawUri;
  if (path.startsWith("file://")) {
    path = path.slice("file://".length);
  }
  const cleanPath = path
    .replace(/^media\//, "")
    .split("?")[0]
    .split("#")[0];
  const parts = cleanPath.split("/");
  const filename = parts[parts.length - 1];
  if (!filename || filename === "." || filename === ".." || filename.includes("\\")) {
    return null;
  }
  return filename;
}

/** Names that a case-insensitive filesystem (the iOS default) treats as one file share a key. */
export function mediaNameKey(filename: string): string {
  return filename.normalize("NFC").toLocaleLowerCase("en-US");
}

import { useCallback, useEffect, useRef, useState } from "react";
import {
  createEntry,
  deleteAllEntries,
  deleteEntry,
  type EntryCursor,
  filterUnreferencedMedia,
  getEntryById,
  getPagedEntries,
  type NewEntryInput,
  type UpdateEntryInput,
  updateEntry,
} from "@/services/db/entries";
import { discardAllDrafts, discardDraft } from "@/services/drafts/store";
import {
  assertMediaPresent,
  deleteMediaFiles,
  deleteUnreferencedMedia,
  releaseMediaCopies,
} from "@/services/media";
import type { Entry } from "@/shared/types";
import { addDays, addMonths, startOfDay, startOfMonth } from "@/shared/utils/dates";
import { reportError } from "@/shared/utils/devLog";
import { removedMedia } from "./mediaDiff";

export type EntryMutation =
  | { type: "add"; entry: Entry }
  | { type: "update"; entry: Entry }
  | { type: "delete"; id: string }
  | { type: "clear" }
  | { type: "reload" };

const mutationListeners = new Set<(mutation: EntryMutation) => void>();

function notifyMutation(mutation: EntryMutation) {
  mutationListeners.forEach((listener) => {
    listener(mutation);
  });
}

export function notifyStoreReload() {
  entryCache.clear();
  notifyMutation({ type: "reload" });
}

export function subscribeMutations(listener: (mutation: EntryMutation) => void) {
  mutationListeners.add(listener);
  return () => {
    mutationListeners.delete(listener);
  };
}

// In-memory single-entry cache for fast lookups
const entryCache = new Map<string, Entry>();

async function cleanupMedia(filenames: string[]): Promise<void> {
  if (!filenames.length) return;
  await deleteMediaFiles({ select: () => filterUnreferencedMedia(filenames) });
}

/** Deletes media files no entry references. */
export async function sweepUnreferencedMedia(): Promise<void> {
  await deleteUnreferencedMedia(async (filenames) => {
    // An empty timeline deletes nothing: after a lost, reset, or unreadable database these files
    // may be the only copy left. The cost is that files left by an interrupted "Delete all", or
    // by a save that failed while the timeline was empty, stay until an entry exists.
    const { entries } = await getPagedEntries({ limit: 1 });
    return entries.length > 0 ? filterUnreferencedMedia(filenames) : [];
  });
}

function inputMedia(input: NewEntryInput | UpdateEntryInput): string[] {
  return [
    ...(input.images ?? []),
    ...(input.audios ?? []),
    ...(input.attachments ?? []).map((attachment) => attachment.uri),
  ];
}

export async function addEntry(input: NewEntryInput): Promise<Entry> {
  const media = inputMedia(input);
  let entry: Entry;
  try {
    await assertMediaPresent(media);
    entry = await createEntry(input);
  } finally {
    releaseMediaCopies(media);
  }
  entryCache.set(entry.id, entry);
  notifyMutation({ type: "add", entry });
  return entry;
}

export async function patchEntry(id: string, input: UpdateEntryInput): Promise<Entry> {
  const media = inputMedia(input);
  let existing: Entry | null;
  let entry: Entry;
  try {
    existing = entryCache.get(id) ?? (await getEntryById(id));
    await assertMediaPresent(media);
    entry = await updateEntry(id, input);
  } finally {
    releaseMediaCopies(media);
  }
  entryCache.set(entry.id, entry);
  notifyMutation({ type: "update", entry });

  // File cleanup starts only after the row committed; failures there must not fail the save.
  if (existing) {
    void cleanupMedia(removedMedia(existing, input)).catch((error) =>
      reportError("entry:cleanupMedia", error)
    );
  }
  return entry;
}

export async function removeEntry(id: string): Promise<void> {
  const uris = await deleteEntry(id);
  await discardDraft(id).catch((error) => reportError("entry:discardDraft", error));
  await cleanupMedia(uris);
  entryCache.delete(id);
  notifyMutation({ type: "delete", id });
}

export async function removeImage(entryId: string, imageIndex: number): Promise<Entry | null> {
  const existing = entryCache.get(entryId) ?? (await getEntryById(entryId));
  if (!existing || imageIndex < 0 || imageIndex >= existing.images.length) return null;
  const nextImages = existing.images.filter((_, i) => i !== imageIndex);
  return patchEntry(entryId, { images: nextImages });
}

export async function removeAudio(entryId: string, audioIndex: number): Promise<Entry | null> {
  const existing = entryCache.get(entryId) ?? (await getEntryById(entryId));
  if (!existing || audioIndex < 0 || audioIndex >= existing.audios.length) return null;
  const nextAudios = existing.audios.filter((_, i) => i !== audioIndex);
  return patchEntry(entryId, { audios: nextAudios });
}

export async function clearAll(): Promise<void> {
  await deleteAllEntries();
  await discardAllDrafts().catch((error) => reportError("entry:discardDrafts", error));
  entryCache.clear();
  notifyMutation({ type: "clear" });
  // Checked against the database, so media a restore published after the clear is kept, and a
  // save still in flight keeps its copy.
  await deleteUnreferencedMedia(filterUnreferencedMedia);
}

export async function fetchEntry(id: string): Promise<Entry | null> {
  const cached = entryCache.get(id);
  if (cached) return cached;
  const fetched = await getEntryById(id);
  if (fetched) entryCache.set(fetched.id, fetched);
  return fetched;
}

interface TimelineFilter {
  monthTs?: number;
  dayTs?: number;
  tagId?: string;
}

function matchesFilter(entry: Entry, { monthTs, dayTs, tagId }: TimelineFilter): boolean {
  if (tagId !== undefined && !entry.tags.some((tag) => tag.id === tagId)) return false;
  if (dayTs !== undefined) {
    const start = startOfDay(dayTs);
    const end = addDays(start, 1);
    return entry.createdAt >= start && entry.createdAt < end;
  }
  if (monthTs !== undefined) {
    const start = startOfMonth(monthTs);
    const end = addMonths(monthTs, 1);
    return entry.createdAt >= start && entry.createdAt < end;
  }
  return true;
}

export interface UseTimelineEntriesOptions extends TimelineFilter {
  pageSize?: number;
}

/**
 * Reactive paginated entry hook for the timeline.
 * Fetches page 1 on mount, supports non-blocking cursor prefetching, and
 * updates in-memory items automatically on mutations.
 */
export function useTimelineEntries(options: UseTimelineEntriesOptions = {}) {
  const { monthTs, dayTs, tagId, pageSize = 50 } = options;
  const [entries, setEntries] = useState<Entry[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isFetchingMore, setIsFetchingMore] = useState(false);
  const [hasMore, setHasMore] = useState(false);

  const nextCursorRef = useRef<EntryCursor | undefined>(undefined);
  const isFetchingMoreRef = useRef(false);
  const entriesRef = useRef(entries);
  entriesRef.current = entries;
  // Bumped by every first-page load so an in-flight older page can't append onto the new list.
  const generationRef = useRef(0);

  const loadInitial = useCallback(async () => {
    const generation = generationRef.current + 1;
    generationRef.current = generation;
    // A page requested from the previous list's cursor must not land on the new one.
    nextCursorRef.current = undefined;
    setIsLoading(true);
    try {
      const res = await getPagedEntries({ monthTs, dayTs, tagId, limit: pageSize });
      if (generationRef.current !== generation) return;
      for (const item of res.entries) {
        entryCache.set(item.id, item);
      }
      setEntries(res.entries);
      setHasMore(res.hasMore);
      nextCursorRef.current = res.nextCursor;
    } finally {
      if (generationRef.current === generation) setIsLoading(false);
    }
  }, [monthTs, dayTs, tagId, pageSize]);

  const loadInitialRef = useRef(loadInitial);
  loadInitialRef.current = loadInitial;

  const loadMore = useCallback(async () => {
    if (!hasMore || isFetchingMoreRef.current || !nextCursorRef.current) {
      return;
    }
    isFetchingMoreRef.current = true;
    setIsFetchingMore(true);
    const generation = generationRef.current;

    try {
      const res = await getPagedEntries({
        cursor: nextCursorRef.current,
        monthTs,
        dayTs,
        tagId,
        limit: pageSize,
      });
      if (generationRef.current !== generation) return;

      for (const item of res.entries) {
        entryCache.set(item.id, item);
      }

      setEntries((prev) => [...prev, ...res.entries]);
      setHasMore(res.hasMore);
      nextCursorRef.current = res.nextCursor;
    } finally {
      isFetchingMoreRef.current = false;
      setIsFetchingMore(false);
    }
  }, [hasMore, monthTs, dayTs, tagId, pageSize]);

  useEffect(() => {
    void loadInitial();
  }, [loadInitial]);

  // Subscribe to real-time mutations
  useEffect(() => {
    return subscribeMutations((mutation) => {
      if (mutation.type === "clear") {
        generationRef.current += 1;
        setEntries([]);
        setIsLoading(false);
        setHasMore(false);
        nextCursorRef.current = undefined;
        return;
      }

      if (mutation.type === "reload") {
        void loadInitialRef.current();
        return;
      }

      if (mutation.type === "delete") {
        setEntries((prev) => prev.filter((e) => e.id !== mutation.id));
        return;
      }

      if (mutation.type === "update") {
        const { entry } = mutation;
        const listed = entriesRef.current.some((e) => e.id === entry.id);
        const matches = matchesFilter(entry, { monthTs, dayTs, tagId });
        if (listed && !matches) {
          setEntries((prev) => prev.filter((e) => e.id !== entry.id));
        } else if (listed) {
          setEntries((prev) => prev.map((e) => (e.id === entry.id ? entry : e)));
        } else if (matches && tagId !== undefined) {
          // An entry that gained this tag may sort below the loaded pages; a reload
          // keeps the keyset cursor from returning it twice.
          void loadInitialRef.current();
        }
        return;
      }

      if (mutation.type === "add") {
        if (matchesFilter(mutation.entry, { monthTs, dayTs, tagId })) {
          setEntries((prev) => {
            const next = [mutation.entry, ...prev.filter((e) => e.id !== mutation.entry.id)];
            return next.sort((a, b) => b.createdAt - a.createdAt);
          });
        }
      }
    });
  }, [monthTs, dayTs, tagId]);

  return {
    entries,
    isLoading,
    isFetchingMore,
    hasMore,
    loadMore,
    refresh: loadInitial,
  };
}

/** Hook to fetch and listen to a single entry's live state. */
export function useEntry(id?: string): Entry | null | undefined {
  const [entry, setEntry] = useState<Entry | null | undefined>(() =>
    id ? entryCache.get(id) : null
  );

  useEffect(() => {
    if (!id) {
      setEntry(null);
      return;
    }

    const cached = entryCache.get(id);
    if (cached) {
      setEntry(cached);
    }

    let active = true;
    let requestVersion = 0;
    const loadEntry = () => {
      const version = requestVersion + 1;
      requestVersion = version;
      void fetchEntry(id)
        .then((result) => {
          if (active && requestVersion === version) setEntry(result);
        })
        .catch(() => {
          if (active && requestVersion === version) setEntry(null);
        });
    };

    loadEntry();

    const unsubscribe = subscribeMutations((mutation) => {
      if (mutation.type === "clear" || (mutation.type === "delete" && mutation.id === id)) {
        requestVersion += 1;
        setEntry(null);
      } else if (mutation.type === "update" && mutation.entry.id === id) {
        requestVersion += 1;
        setEntry(mutation.entry);
      } else if (mutation.type === "reload") {
        loadEntry();
      }
    });

    return () => {
      active = false;
      unsubscribe();
    };
  }, [id]);

  return entry;
}

/** The entry store actions, grouped in one object. */
export function useEntries() {
  return {
    addEntry,
    patchEntry,
    removeEntry,
    removeImage,
    removeAudio,
    clearAll,
    getEntry: fetchEntry,
  };
}

import { useFocusEffect } from "@react-navigation/native";
import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
import { useCallback, useRef, useState } from "react";
import { StyleSheet, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useTimelineEntries } from "@/modules/entry";
import { TimelineSearchLayer } from "@/modules/search";
import { AddEntryFab, FAB_CLEARANCE, TimelineFeed, TimelineHeader } from "@/modules/timeline";
import type { RootStackParamList } from "@/navigation/types";
import { requestNotificationPermission } from "@/services/notifications";
import { CalendarPicker } from "@/shared/pickers";
import { startOfDay } from "@/shared/utils/dates";
import { useTheme } from "@/theme";

type Nav = NativeStackNavigationProp<RootStackParamList, "Timeline">;

// Let the timeline settle before the OS permission dialog interrupts.
const PERMISSION_PROMPT_DELAY_MS = 1200;

export function TimelineScreen({ navigation }: { navigation: Nav }) {
  const insets = useSafeAreaInsets();
  const { colors } = useTheme();

  const [dayPickerOpen, setDayPickerOpen] = useState(false);
  const [searchActive, setSearchActive] = useState(false);

  const permissionAskedRef = useRef(false);

  // Focus, not mount: onboarding lands here via both goBack and replace.
  useFocusEffect(
    useCallback(() => {
      if (permissionAskedRef.current) return;
      permissionAskedRef.current = true;

      const timer = setTimeout(
        () => void requestNotificationPermission(),
        PERMISSION_PROMPT_DELAY_MS
      );
      return () => clearTimeout(timer);
    }, [])
  );

  // Continuous newest-to-oldest feed across all time with infinite prefetching
  const { entries, loadMore } = useTimelineEntries();

  const openDay = useCallback(
    (ts: number) => navigation.navigate("Day", { dayTs: startOfDay(ts) }),
    [navigation]
  );

  const closeSearch = useCallback(() => setSearchActive(false), []);

  const openEntryFromSearch = useCallback(
    (entryId: string) => {
      setSearchActive(false);
      navigation.navigate("Compose", { entryId, mode: "view" });
    },
    [navigation]
  );

  const openTagFromSearch = useCallback(
    (tagId: string) => {
      setSearchActive(false);
      navigation.push("Tag", { tagId });
    },
    [navigation]
  );

  return (
    <View style={[styles.flex, { backgroundColor: colors.background }]}>
      <TimelineHeader
        onOpenSearch={() => setSearchActive(true)}
        onOpenCalendar={() => setDayPickerOpen(true)}
        onOpenSettings={() => navigation.navigate("Settings")}
      />

      <TimelineFeed
        entries={entries}
        showDates
        bottomInset={FAB_CLEARANCE + insets.bottom}
        emptyTitle="A quiet timeline"
        emptyBody="Tap + to write, or open the calendar."
        animateFirst
        onOpenDay={openDay}
        onEndReached={loadMore}
      />

