import { useSyncExternalStore } from "react";

export interface BackupStatus {
  isExporting: boolean;
  isImporting: boolean;
}

let activeExportController: AbortController | null = null;
let activeImportController: AbortController | null = null;
const backupStatusListeners = new Set<() => void>();
let cachedStatus: BackupStatus = { isExporting: false, isImporting: false };

function notifyBackupStatusChange() {
  for (const listener of backupStatusListeners) {
    listener();
  }
}

export function getBackupStatus(): BackupStatus {
  const isExporting = activeExportController !== null;
  const isImporting = activeImportController !== null;
  if (cachedStatus.isExporting !== isExporting || cachedStatus.isImporting !== isImporting) {
    cachedStatus = { isExporting, isImporting };
  }
  return cachedStatus;
}

export function subscribeBackupStatus(listener: () => void): () => void {
  backupStatusListeners.add(listener);
  return () => {
    backupStatusListeners.delete(listener);
  };
}

/**
 * Hook to reactively observe if a backup export or import operation is in flight.
 */
export function useBackupStatus(): BackupStatus {
  return useSyncExternalStore(subscribeBackupStatus, getBackupStatus);
}

export function setExportController(controller: AbortController | null): void {
  activeExportController = controller;
  notifyBackupStatusChange();
}

export function setImportController(controller: AbortController | null): void {
  activeImportController = controller;
  notifyBackupStatusChange();
}

export function cancelActiveBackup(): boolean {
  if (activeExportController) {
    activeExportController.abort();
    activeExportController = null;
    notifyBackupStatusChange();
    return true;
  }
  return false;
}

export function cancelActiveImport(): boolean {
  if (activeImportController) {
    activeImportController.abort();
    activeImportController = null;
    notifyBackupStatusChange();
    return true;
  }
  return false;
}

import { FONTSOURCE_VERSIONS } from "./catalog.ts";
import type { FontName, FontSource } from "./types";

/**
 * Converts a canonical font family name into a package slug for CDN lookup.
 * E.g. "Source Sans 3" -> "source-sans-3", "Plus Jakarta Sans" -> "plus-jakarta-sans".
 */
export function fontNameToSlug(fontName: string): string {
  return fontName
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

/**
 * Resolves a font family name to its remote downloadable TTF source.
 */
export function resolveFontSource(fontName: FontName): FontSource {
  const version = FONTSOURCE_VERSIONS.get(fontName);
  if (!version) throw new Error(`No pinned font source for "${fontName}"`);
  const slug = fontNameToSlug(fontName);
  const url = `https://cdn.jsdelivr.net/fontsource/fonts/${slug}@${version}/latin-400-normal.ttf`;
  return {
    family: fontName,
    url,
  };
}

import { Directory, File, Paths } from "expo-file-system";

import { logDevWarning } from "@/shared/utils/devLog";
import { fontNameToSlug } from "./resolver";
import type { FontName } from "./types";

function fontsDirectory(): Directory {
  return new Directory(Paths.document, "fonts");
}

function ensureDirectory(): Directory {
  const dir = fontsDirectory();
  dir.create({ idempotent: true, intermediates: true });
  return dir;
}

export function getFontFile(fontName: FontName): File {
  const dir = fontsDirectory();
  const filename = `${fontNameToSlug(fontName)}.ttf`;
  return new File(dir, filename);
}

export const fontCache = {
  /**
   * Checks whether the font file exists in local storage.
   */
  has(fontName: FontName): boolean {
    try {
      const file = getFontFile(fontName);
      return file.exists;
    } catch {
      return false;
    }
  },

  /**
   * Returns the File object for the given font name, or null if it does not exist.
   */
  get(fontName: FontName): File | null {
    try {
      const file = getFontFile(fontName);
      return file.exists ? file : null;
    } catch {
      return null;
    }
  },

  /**
   * Downloads a remote font file and saves it into the local cache.
   */
  async save(fontName: FontName, url: string): Promise<File> {
    ensureDirectory();
    const dest = getFontFile(fontName);
    return File.downloadFileAsync(url, dest, { idempotent: true });
  },

  /**
   * Deletes a cached font file.
   */
  async remove(fontName: FontName): Promise<void> {
    try {
      const file = getFontFile(fontName);
      if (file.exists) {
        file.delete();
      }
    } catch (error) {
      logDevWarning("fontCache:remove", error);
    }
  },

  /**
   * Clears all cached font files.
   */
  async clear(): Promise<void> {
    try {
      const dir = fontsDirectory();
      if (dir.exists) {
        dir.delete();
        ensureDirectory();
      }
    } catch (error) {
      logDevWarning("fontCache:clear", error);
    }
  },
};

import * as Font from "expo-font";

import { logDevWarning } from "@/shared/utils/devLog";
import { fontCache, getFontFile } from "./cache";
import { DEFAULT_FONT, getFonts, hasFont } from "./catalog";
import { resolveFontSource } from "./resolver";
import type { FontLoadResult, FontName } from "./types";

class FontManager {
  private inFlightLoads = new Map<string, Promise<FontLoadResult>>();

  /**
   * Returns all available font family names in the catalog.
   */
  getFonts(): readonly FontName[] {
    return getFonts();
  }

  /**
   * Checks whether a font name is present in the catalog.
   */
  hasFont(fontName: string): boolean {
    return hasFont(fontName);
  }

  /**
   * The default bootstrap font, bundled with the app.
   */
  getDefaultFont(): FontName {
    return DEFAULT_FONT;
  }

  /**
   * Synchronously checks if a font is already loaded and ready for rendering.
   * Default font ("Source Sans 3") is always considered loaded via app bundle.
   */
  isLoaded(fontName: FontName): boolean {
    if (fontName === DEFAULT_FONT) {
      return true;
    }
    return Font.isLoaded(fontName);
  }

  /**
   * Checks whether the font file is downloaded and cached locally.
   */
  isCached(fontName: FontName): boolean {
    if (fontName === DEFAULT_FONT) {
      return true;
    }
    return fontCache.has(fontName);
  }

  /**
   * Loads a font by canonical family name.
   *
   * Coordinates:
   *   1. Deduplication of concurrent in-flight requests.
   *   2. Cache lookup.
   *   3. On-demand downloading.
   *   4. expo-font registration.
   *   5. Auto-recovery from corrupt cache files.
   *   6. Fallback to Source Sans 3 on failure.
   */
  async load(fontName: FontName): Promise<FontLoadResult> {
    // 1. Validation against catalog
    if (!hasFont(fontName)) {
      logDevWarning("fontManager:load", `Font "${fontName}" does not exist in catalog.`);
      return { success: false, fontFamily: DEFAULT_FONT };
    }

    // 2. Default font is bundled
    if (fontName === DEFAULT_FONT) {
      return { success: true, fontFamily: DEFAULT_FONT };
    }

    // 3. Already loaded in React Native font system
    if (Font.isLoaded(fontName)) {
      return { success: true, fontFamily: fontName };
    }

    // 4. Deduplicate concurrent in-flight requests
    const existingPromise = this.inFlightLoads.get(fontName);
    if (existingPromise) {
      return existingPromise;
    }

    const loadPromise = this.executeLoad(fontName);
    this.inFlightLoads.set(fontName, loadPromise);

    try {
      return await loadPromise;
    } finally {
      this.inFlightLoads.delete(fontName);
    }
  }

  /**
   * Preloads a font in the background without blocking.
   */
  async preload(fontName: FontName): Promise<FontLoadResult> {
    return this.load(fontName);
  }

  /**
   * Removes a font file from the local cache.
   */
  async remove(fontName: FontName): Promise<void> {
    await fontCache.remove(fontName);
  }

  /**
   * Clears the entire font cache.
   */
  async clearCache(): Promise<void> {
    await fontCache.clear();
  }

  private async executeLoad(fontName: FontName): Promise<FontLoadResult> {
    // If cached, try loading the cached file first
    if (fontCache.has(fontName)) {
      try {
        const file = getFontFile(fontName);
        await Font.loadAsync({ [fontName]: file.uri });
        return { success: true, fontFamily: fontName };
      } catch (error) {
        logDevWarning(`fontManager:cachedLoadFailed (${fontName}) - invalidating cache`, error);
        // Invalidate corrupt cache file and attempt fresh download below
        await fontCache.remove(fontName);
      }
    }

    // Download from remote font source
    try {
      const source = resolveFontSource(fontName);
      const savedFile = await fontCache.save(fontName, source.url);
      await Font.loadAsync({ [fontName]: savedFile.uri });
      return { success: true, fontFamily: fontName };
    } catch (error) {
      logDevWarning(`fontManager:downloadOrLoadFailed (${fontName})`, error);
      return { success: false, fontFamily: DEFAULT_FONT };
    }
  }
}

export const fontManager = new FontManager();

import {
  ARCHIVE_FORMAT,
  ARCHIVE_SCHEMA_VERSION,
  type BackupManifest,
  type BackupTimelineData,
  MANIFEST_FILENAME,
  TIMELINE_DATA_FILENAME,
} from "./types.ts";

/** Rejects backups whose entries refer to media that was not actually archived. */
export function assertBackupMediaReferences(
  entries: BackupTimelineData["entries"],
  mediaNames: ReadonlySet<string>
): void {
  for (const entry of entries) {
    const references = [
      ...(entry.images ?? []),
      ...(entry.audios ?? []),
      ...(entry.attachments?.map((attachment) => attachment.uri) ?? []),
    ];
    for (const filename of references) {
      if (!mediaNames.has(filename)) {
        throw new Error(`Invalid backup file: media file ${filename} is missing.`);
      }
    }
  }
}

export interface BackupCountsInput {
  manifest: BackupManifest;
  timeline: BackupTimelineData;
  mediaCount: number;
}

/** Rejects archives whose contents disagree with the counts their manifest declares. */
export function assertBackupCounts({ manifest, timeline, mediaCount }: BackupCountsInput): void {
  if (timeline.entries.length !== manifest.counts.entry) {
    throw new Error(
      `Backup entry count mismatch (${timeline.entries.length} entries, manifest specifies ${manifest.counts.entry}).`
    );
  }
  if (timeline.tags.length !== manifest.counts.tag) {
    throw new Error(
      `Backup tag count mismatch (${timeline.tags.length} tags, manifest specifies ${manifest.counts.tag}).`
    );
  }
  if (mediaCount !== manifest.counts.media) {
    throw new Error(
      `Backup media count mismatch (${mediaCount} media files, manifest specifies ${manifest.counts.media}).`
    );
  }
}

function isNonNegativeInteger(value: unknown): boolean {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

/** A restorable media reference: a non-empty bare filename with no path or traversal. */
function isBareFilename(value: unknown): value is string {
  return (
    typeof value === "string" &&
    value.length > 0 &&
    !value.includes("/") &&
    !value.includes("\\") &&
    value !== "." &&
    value !== ".."
  );
}

/** Validates the backup manifest metadata. */
export function assertBackupManifest(data: unknown): asserts data is BackupManifest {
  if (!data || typeof data !== "object") {
    throw new Error("Invalid backup manifest: not an object.");
  }
  const obj = data as Record<string, unknown>;
  if (obj.format !== ARCHIVE_FORMAT) {
    throw new Error(`Invalid backup format: ${String(obj.format)}`);
  }
  if (typeof obj.version !== "number" || !Number.isInteger(obj.version) || obj.version < 1) {
    throw new Error(`Invalid backup file: unsupported archive version (${String(obj.version)}).`);
  }
  if (obj.version > ARCHIVE_SCHEMA_VERSION) {
    throw new Error(`Unsupported backup version (${obj.version}). Update OpenLog.`);
  }
  if (typeof obj.createdAt !== "number" || !Number.isFinite(obj.createdAt)) {
    throw new Error("Invalid backup manifest: createdAt is missing or invalid.");
  }
  if (typeof obj.appVersion !== "string" || !obj.appVersion) {
    throw new Error("Invalid backup manifest: appVersion is missing.");
  }
  if (!obj.counts || typeof obj.counts !== "object") {
    throw new Error("Invalid backup manifest: counts is missing.");
  }
  const counts = obj.counts as Record<string, unknown>;
  if (
    !isNonNegativeInteger(counts.entry) ||
    !isNonNegativeInteger(counts.tag) ||
    !isNonNegativeInteger(counts.media)
  ) {
    throw new Error("Invalid backup manifest: counts must be non-negative integers.");
  }
}

/** Validates timeline data, including the uniqueness and reference rules the database enforces. */
export function assertBackupTimelineData(data: unknown): asserts data is BackupTimelineData {
  if (!data || typeof data !== "object") {
    throw new Error("Invalid backup timeline: not an object.");
  }
  const obj = data as Record<string, unknown>;

  if (!Array.isArray(obj.tags)) {
    throw new Error("Invalid backup timeline: tags must be an array.");
  }
  const tagIds = new Set<string>();
  const tagKeys = new Set<string>();
  for (const tag of obj.tags) {
    if (!tag || typeof tag !== "object") {
      throw new Error("Invalid backup tag: malformed item.");
    }
    const t = tag as Record<string, unknown>;
    if (typeof t.id !== "string" || !t.id) throw new Error("Invalid backup tag: missing id.");
    if (typeof t.name !== "string" || !t.name) throw new Error("Invalid backup tag: missing name.");
    if (typeof t.key !== "string") throw new Error("Invalid backup tag: key is required.");
    if (typeof t.colorId !== "string" || !t.colorId)
      throw new Error("Invalid backup tag: missing colorId.");
    if (typeof t.createdAt !== "number" || !Number.isFinite(t.createdAt)) {
      throw new Error("Invalid backup tag: createdAt is required.");
    }
    if (typeof t.updatedAt !== "number" || !Number.isFinite(t.updatedAt)) {
      throw new Error("Invalid backup tag: updatedAt is required.");
    }
    if (tagIds.has(t.id)) throw new Error("Invalid backup tag: duplicate id.");
    if (tagKeys.has(t.key)) throw new Error("Invalid backup tag: duplicate name.");
    tagIds.add(t.id);
    tagKeys.add(t.key);
  }

  if (!Array.isArray(obj.entries)) {
    throw new Error("Invalid backup timeline: entries must be an array.");
  }
  const entryIds = new Set<string>();
  for (const entry of obj.entries) {
    if (!entry || typeof entry !== "object") {
      throw new Error("Invalid backup entry: malformed item.");
    }
    const e = entry as Record<string, unknown>;
    if (typeof e.id !== "string" || !e.id) throw new Error("Invalid backup entry: missing id.");
    if (entryIds.has(e.id)) throw new Error("Invalid backup entry: duplicate id.");
    entryIds.add(e.id);
    if (typeof e.createdAt !== "number" || !Number.isFinite(e.createdAt)) {
      throw new Error("Invalid backup entry: createdAt is required.");
    }
    if (typeof e.updatedAt !== "number" || !Number.isFinite(e.updatedAt)) {
      throw new Error("Invalid backup entry: updatedAt is required.");
    }
    if (e.text !== undefined && e.text !== null && typeof e.text !== "string") {
      throw new Error("Invalid backup entry: text must be a string or null.");
    }
    if (e.images !== undefined && (!Array.isArray(e.images) || !e.images.every(isBareFilename))) {
      throw new Error("Invalid backup entry: images must be media filenames.");
    }
    if (e.audios !== undefined && (!Array.isArray(e.audios) || !e.audios.every(isBareFilename))) {
      throw new Error("Invalid backup entry: audios must be media filenames.");
    }
    if (e.attachments !== undefined) {
      if (!Array.isArray(e.attachments)) {
        throw new Error("Invalid backup entry: attachments must be an array.");
      }
      for (const item of e.attachments as unknown[]) {
        const attachment =
          item && typeof item === "object" ? (item as Record<string, unknown>) : null;
        if (!attachment || !isBareFilename(attachment.uri)) {
          throw new Error("Invalid backup entry: attachment uris must be media filenames.");
        }
        if (typeof attachment.name !== "string") {
          throw new Error("Invalid backup entry: attachment names must be strings.");
        }
        if (attachment.mimeType !== undefined && typeof attachment.mimeType !== "string") {
          throw new Error("Invalid backup entry: attachment types must be strings.");
        }
      }
    }
    if (e.tagIds !== undefined) {
      if (!Array.isArray(e.tagIds)) {
        throw new Error("Invalid backup entry: tagIds must be an array.");
      }
      const entryTagIds = new Set<string>();
      for (const tagId of e.tagIds) {
        if (typeof tagId !== "string" || !tagIds.has(tagId)) {
          throw new Error("Invalid backup entry: tagIds must reference backup tags.");
        }
        if (entryTagIds.has(tagId)) throw new Error("Invalid backup entry: duplicate tag.");
        entryTagIds.add(tagId);
      }
    }
    if (e.location !== undefined && e.location !== null) {
      if (typeof e.location !== "object") {
        throw new Error("Invalid backup entry: location must be an object or null.");
      }
      const loc = e.location as Record<string, unknown>;
      if (typeof loc.latitude !== "number" || typeof loc.longitude !== "number") {
        throw new Error("Invalid backup entry: location coordinates must be numbers.");
      }
      if (loc.name !== undefined && loc.name !== null && typeof loc.name !== "string") {
        throw new Error("Invalid backup entry: location name must be a string.");
      }
    }
  }

  if (obj.settings !== undefined) {
    if (typeof obj.settings !== "object" || obj.settings === null || Array.isArray(obj.settings)) {
      throw new Error("Invalid backup timeline: settings must be an object.");
    }
    if (!Object.values(obj.settings).every((value) => typeof value === "string")) {
      throw new Error("Invalid backup timeline: settings values must be strings.");
    }
  }
  if (
    obj.preferences !== undefined &&
    (typeof obj.preferences !== "object" || obj.preferences === null)
  ) {
    throw new Error("Invalid backup timeline: preferences must be an object.");
  }
}

export const BACKUP_LIMITS = {
  archiveBytes: 512 * 1024 * 1024,
  uncompressedBytes: 2 * 1024 * 1024 * 1024,
  memberBytes: 256 * 1024 * 1024,
  timelineDataBytes: 64 * 1024 * 1024,
  manifestBytes: 64 * 1024 * 1024,
  media: 100_000,
} as const;

/** Archive reads pause for the UI after this many bytes so progress renders and Cancel can land. */
export const BACKUP_YIELD_BYTES = 2 * 1024 * 1024;

export const IMPORT_SAFETY_BUFFER_BYTES = 50 * 1024 * 1024;

export interface ExportSizeLimitsInput {
  manifestBytes: number;
  timelineBytes: number;
  mediaBytes: readonly number[];
}

/** Keeps successful exports within the limits enforced by import. */
export function assertBackupExportSizeLimits({
  manifestBytes,
  timelineBytes,
  mediaBytes,
}: ExportSizeLimitsInput): void {
  if (manifestBytes > BACKUP_LIMITS.manifestBytes) {
    throw new Error("Backup manifest is too large to import.");
  }
  if (timelineBytes > BACKUP_LIMITS.timelineDataBytes) {
    throw new Error("Backup data is too large to import.");
  }
  if (mediaBytes.length > BACKUP_LIMITS.media) {
    throw new Error("Backup contains too many media files to import.");
  }
  const total = manifestBytes + timelineBytes + mediaBytes.reduce((sum, bytes) => sum + bytes, 0);
  if (total > BACKUP_LIMITS.uncompressedBytes) {
    throw new Error("Backup expands beyond the import limit.");
  }
  if (mediaBytes.some((bytes) => bytes > BACKUP_LIMITS.memberBytes)) {
    throw new Error("A media file is too large to include in a restorable backup.");
  }
}

export function assertBackupArchiveSize(bytes: number): void {
  if (bytes > BACKUP_LIMITS.archiveBytes) {
    throw new Error("Backup is too large to import.");
  }
}

export interface StoragePreflightParams {
  archiveBytes: number;
  existingTimelineBytes: number;
  uncompressedBytes?: number;
  expectedArchiveBytes?: number;
  safetyBufferBytes?: number;
}

/**
 * Calculates the required free disk storage before an import begins.
 * Uses exact uncompressedBytes when the archive size matches expectedArchiveBytes;
 * otherwise conservatively reserves the full allowed expansion capacity up to BACKUP_LIMITS.uncompressedBytes.
 */
export function calculateRequiredImportBytes({
  archiveBytes,
  existingTimelineBytes,
  uncompressedBytes,
  expectedArchiveBytes,
  safetyBufferBytes = IMPORT_SAFETY_BUFFER_BYTES,
}: StoragePreflightParams): number {
  const isSizeUnchanged =
    expectedArchiveBytes !== undefined && expectedArchiveBytes === archiveBytes;
  const estimatedStagingBytes =
    uncompressedBytes !== undefined && uncompressedBytes > 0 && isSizeUnchanged
      ? Math.min(uncompressedBytes, BACKUP_LIMITS.uncompressedBytes)
      : Math.min(Math.max(archiveBytes * 4, 10 * 1024 * 1024), BACKUP_LIMITS.uncompressedBytes);

  return archiveBytes + estimatedStagingBytes + existingTimelineBytes + safetyBufferBytes;
}

/**
 * Validates that an archive path adheres to the expected format:
 * - "manifest.json"
 * - "timeline.json"
 * - "media/<filename>" (non-empty, single segment, no traversal or backslashes)
 * Rejects path traversal, duplicate paths, and unexpected paths.
 */
export function validateArchivePath(name: string, seenPaths?: Set<string>): void {
  if (name.startsWith("/") || name.startsWith("\\") || name.includes("..") || name.includes("\\")) {
    throw new Error("Invalid backup file: unexpected archive path.");
  }
  if (seenPaths?.has(name)) {
    if (name === MANIFEST_FILENAME) {
      throw new Error("Invalid backup file: duplicate manifest.");
    }
    if (name === TIMELINE_DATA_FILENAME) {
      throw new Error("Invalid backup file: duplicate timeline data.");
    }
    throw new Error("Invalid backup file: duplicate archive path.");
  }
  if (name === MANIFEST_FILENAME || name === TIMELINE_DATA_FILENAME) {
    return;
  }
  if (name.startsWith("media/")) {
    const filename = name.slice("media/".length);
    if (
      filename.length === 0 ||
      filename.includes("/") ||
      filename === "." ||
      filename === ".." ||
      filename.includes("\\")
    ) {
      throw new Error("Invalid backup file: unexpected archive path.");
    }
    return;
  }
  throw new Error("Invalid backup file: unexpected archive path.");
}

export function extractMediaFilename(path: string): string {
  validateArchivePath(path);
  if (!path.startsWith("media/")) {
    throw new Error("Invalid media path in backup archive.");
  }
  return path.slice("media/".length);
}

let activeExports = 0;
let exportsDone: Promise<void> | null = null;
let resolveExportsDone: (() => void) | null = null;
let gateGeneration = 0;

/** Exports may overlap, so the gate stays closed until the last one releases it. */
export function acquireExportGate(): void {
  if (resolveImportGate) throw new Error("An import is in progress.");
  gateGeneration += 1;
  activeExports += 1;
  exportsDone ??= new Promise<void>((resolve) => {
    resolveExportsDone = resolve;
  });
}

export function releaseExportGate(): void {
  if (activeExports === 0) return;
  activeExports -= 1;
  if (activeExports > 0) return;
  resolveExportsDone?.();
  resolveExportsDone = null;
  exportsDone = null;
}

export async function waitForExportGate(): Promise<void> {
  while (exportsDone) await exportsDone;
}

let activeImportGatePromise: Promise<void> | null = null;
let resolveImportGate: (() => void) | null = null;

export function acquireImportGate(): void {
  if (resolveImportGate) throw new Error("An import is already in progress.");
  if (activeExports > 0) throw new Error("An export is in progress.");
  gateGeneration += 1;
  activeImportGatePromise = new Promise<void>((resolve) => {
    resolveImportGate = resolve;
  });
}

export function releaseImportGate(): void {
  resolveImportGate?.();
  resolveImportGate = null;
  activeImportGatePromise = null;
}

export async function waitForImportGate(): Promise<void> {
  while (activeImportGatePromise) await activeImportGatePromise;
}

/** Changes whenever an export or import acquires its gate. */
export function backupGateGeneration(): number {
  return gateGeneration;
}

/**
 * Resolves once neither gate is held, with the generation at that moment. A caller whose
 * generation still matches later knows no export or import has started since.
 */
export async function waitForBackupGates(): Promise<number> {
  for (;;) {
    if (exportsDone) await exportsDone;
    else if (activeImportGatePromise) await activeImportGatePromise;
    else return gateGeneration;
  }
}

