  }

  if (cachedModule && !isHandlerConfigured) {
    try {
      cachedModule.setNotificationHandler({
        handleNotification: async () => ({
          shouldPlaySound: true,
          shouldSetBadge: false,
          shouldShowBanner: true,
          shouldShowList: true,
        }),
      });
      isHandlerConfigured = true;
    } catch (error) {
      logDevWarning("notifications:setHandler", error);
    }
  }

  return cachedModule;
}

let channelsConfigured = false;

async function ensureBackupChannels(Notifications: NotificationsModule): Promise<void> {
  if (Platform.OS !== "android" || channelsConfigured) {
    return;
  }

  try {
    await Notifications.setNotificationChannelAsync("backup", {
      name: "Backup & Import",
      importance: Notifications.AndroidImportance.HIGH,
      vibrationPattern: [0, 250, 250, 250],
      lightColor: "#8B5CF6",
    });
    await Notifications.setNotificationChannelAsync("backup-progress", {
      name: "Backup & Import Progress",
      importance: Notifications.AndroidImportance.LOW,
      enableVibrate: false,
      sound: null,
    });
    channelsConfigured = true;
  } catch (error) {
    logDevWarning("notifications:ensureBackupChannels", error);
  }
}

/** Requests notification permission if not granted; the OS itself never re-prompts after a decision. */
export async function requestNotificationPermission(): Promise<boolean> {
  const Notifications = getNotifications();
  if (!Notifications) {
    return false;
  }

  try {
    const { status: existingStatus } = await Notifications.getPermissionsAsync();
    let finalStatus = existingStatus;

    // The OS shows the dialog only while undecided, so repeated calls never nag.
    if (existingStatus !== "granted") {
      const { status } = await Notifications.requestPermissionsAsync();
      if (existingStatus === "undetermined") {
        analytics.capture("notification_permission_prompted", {
          granted: status === "granted",
        });
      }
      finalStatus = status;
    }

    if (Platform.OS === "android") {
      await ensureBackupChannels(Notifications);
    }

    return finalStatus === "granted";
  } catch (error) {
    logDevWarning("notifications:requestPermission", error);
    return false;
  }
}

/**
 * Dispatches an immediate local notification.
 */
export async function sendLocalNotification(
  title: string,
  body: string,
  data?: Record<string, unknown>
): Promise<void> {
  const Notifications = getNotifications();
  if (!Notifications) {
    return;
  }

  try {
    await Notifications.scheduleNotificationAsync({
      content: {
        title,
        body,
        sound: true,
        data,
      },
      trigger: null,
    });
  } catch (error) {
    logDevWarning("notifications:sendLocalNotification", error);
  }
}

const BACKUP_NOTIFICATION_ID = "openlog-backup-progress";

/**
 * Shows or updates an ongoing notification in the notification bar while backup/import is in progress.
 */
export async function notifyBackupProgress(title: string, body: string): Promise<void> {
  const Notifications = getNotifications();
  if (!Notifications) return;

  await ensureBackupChannels(Notifications);

  try {
    await Notifications.scheduleNotificationAsync({
      identifier: BACKUP_NOTIFICATION_ID,
      content: {
        title,
        body,
        sound: false,
        sticky: true,
        autoDismiss: false,
      },
      trigger: Platform.OS === "android" ? { channelId: "backup-progress" } : null,
    });
  } catch (error) {
    logDevWarning("notifications:notifyBackupProgress", error);
  }
}

/**
 * Dismisses the ongoing backup/import notification (e.g. on cancellation).
 */
export async function dismissBackupProgressNotification(): Promise<void> {
  const Notifications = getNotifications();
  if (!Notifications) return;

  try {
    await Notifications.dismissNotificationAsync(BACKUP_NOTIFICATION_ID);
  } catch (error) {
    logDevWarning("notifications:dismissBackupProgress", error);
  }
}

/**
 * Notifies the user when an archive export has completed packing and saving.
 */
export async function notifyBackupExportComplete(
  entryCount: number,
  byteSize?: number
): Promise<void> {
  const Notifications = getNotifications();
  if (!Notifications) return;

  await ensureBackupChannels(Notifications);

  const sizeText = byteSize ? ` (${formatBytes(byteSize)})` : "";
  try {
    await Notifications.scheduleNotificationAsync({
      identifier: BACKUP_NOTIFICATION_ID,
      content: {
        title: "Backup saved",
        body: `${entryCount.toLocaleString()} ${entryCount === 1 ? "entry" : "entries"}${sizeText}.`,
        sound: true,
        sticky: false,
        autoDismiss: true,
      },
      trigger: Platform.OS === "android" ? { channelId: "backup" } : null,
    });
  } catch (error) {
    logDevWarning("notifications:notifyBackupExportComplete", error);
  }
}

/**
 * Notifies the user when an archive import has completed.
 */
export async function notifyBackupImportComplete(importedCount: number): Promise<void> {
  const Notifications = getNotifications();
  if (!Notifications) return;

  await ensureBackupChannels(Notifications);

  try {
    await Notifications.scheduleNotificationAsync({
      identifier: BACKUP_NOTIFICATION_ID,
      content: {
        title: "Backup imported",
        body: `${importedCount.toLocaleString()} ${importedCount === 1 ? "entry" : "entries"} imported.`,
        sound: true,
        sticky: false,
        autoDismiss: true,
      },
      trigger: Platform.OS === "android" ? { channelId: "backup" } : null,
    });
  } catch (error) {
    logDevWarning("notifications:notifyBackupImportComplete", error);
  }
}

/**
 * Notifies the user when an archive export or import operation fails.
 */
export async function notifyBackupError(title: string, body: string): Promise<void> {
  const Notifications = getNotifications();
  if (!Notifications) return;

  await ensureBackupChannels(Notifications);

  try {
    await Notifications.scheduleNotificationAsync({
      identifier: BACKUP_NOTIFICATION_ID,
      content: {
        title,
        body,
        sound: true,
        sticky: false,
        autoDismiss: true,
      },
      trigger: Platform.OS === "android" ? { channelId: "backup" } : null,
    });
  } catch (error) {
    logDevWarning("notifications:notifyBackupError", error);
  }
}

import { StyleSheet, TextInput, View } from "react-native";

import { useProfile } from "@/modules/profile";
import { SettingsGroup, SettingsScreenScroll } from "@/modules/settings";
import { ThemedText } from "@/shared/components/ThemedText";
import { space, typography, useTheme } from "@/theme";

// Local profile: the name is stored on this device only.
export function ProfileSettingsScreen() {
  const { theme } = useTheme();
  const { colors } = theme;
  const { name, setName } = useProfile();

  return (
    <SettingsScreenScroll>
      <SettingsGroup label="ACCOUNT">
        <View style={styles.fieldRow}>
          <ThemedText style={[typography.settingLabel, { color: colors.textSecondary }]}>
            Name
          </ThemedText>
          <TextInput
            value={name ?? ""}
            onChangeText={setName}
            placeholder="Your name"
            placeholderTextColor={colors.textTertiary}
            autoCapitalize="words"
            autoCorrect={false}
            maxLength={40}
            style={[
              styles.nameInput,
              typography.settingLabel,
              { color: colors.text, borderBottomColor: colors.separator },
            ]}
          />
        </View>
      </SettingsGroup>
    </SettingsScreenScroll>
  );
}

const styles = StyleSheet.create({
  fieldRow: {
    paddingVertical: space.sm,
    gap: space.xs,
  },
  nameInput: {
    paddingVertical: space.xs,
    paddingHorizontal: 0,
    borderBottomWidth: StyleSheet.hairlineWidth,
  },
});

import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { StyleSheet, View } from "react-native";
import { useProfile } from "@/modules/profile";
import { SettingsGroup, SettingsRow, SettingsScreenScroll } from "@/modules/settings";
import type { RootStackParamList } from "@/navigation/types";
import { useBiometricLock } from "@/services/auth";
import { APP_VERSION } from "@/shared/utils";
import { ACCENT_OPTIONS, type ThemeMode, usePreferences, useTheme } from "@/theme";

type Props = NativeStackScreenProps<RootStackParamList, "Settings">;

const THEME_LABELS: Record<ThemeMode, string> = {
  light: "Light",
  dark: "Dark",
  system: "System",
};

/**
 * Settings hub — deliberately short. One row per category; each pushes its
 * own screen (registered in App.tsx) so categories can grow without
 * lengthening this list. Category screens compose the section editors
 * from `modules/settings`; generic building blocks live in `core/`.
 */
export function SettingsScreen({ navigation }: Props) {
  const { theme, isDark } = useTheme();
  const { preferences } = usePreferences();
  const { name } = useProfile();
  const { enabled: biometricLock } = useBiometricLock();
  const { colors } = theme;

  const { appearance } = preferences;

  const accent = ACCENT_OPTIONS.find((a) => a.id === appearance.accent) ?? ACCENT_OPTIONS[0];
  const accentColor = isDark ? accent.colorDark : accent.colorLight;

  return (
    <SettingsScreenScroll>
      <SettingsGroup>
        <SettingsRow
          icon="user"
          title="Profile"
          subtitle={name?.trim() || "Your local profile"}
          onPress={() => navigation.navigate("SettingsProfile")}
        />

        <SettingsRow
          icon="droplet"
          title="Appearance"
          subtitle={`${THEME_LABELS[appearance.mode]} · ${accent.label}`}
          badge={
            <View
              style={[
                styles.accentSwatch,
                { backgroundColor: accentColor, borderColor: colors.separator },
              ]}
            />
          }
          onPress={() => navigation.navigate("SettingsAppearance")}
        />

        <SettingsRow
          icon="eye"
          title="Accessibility"
          subtitle="Text size & animation level"
          onPress={() => navigation.navigate("SettingsAccessibility")}
        />

        <SettingsRow
          icon="lock"
          title="Privacy & Data"
          subtitle={biometricLock ? "App lock on" : "App lock off"}
          onPress={() => navigation.navigate("SettingsPrivacy")}
        />

        <SettingsRow
          icon="info"
          title="About"
          subtitle={APP_VERSION ? `Version ${APP_VERSION}` : "App info"}
          onPress={() => navigation.navigate("SettingsAbout")}
        />
      </SettingsGroup>
    </SettingsScreenScroll>
  );
}

const styles = StyleSheet.create({
  accentSwatch: {
    width: 22,
    height: 22,
    borderRadius: 11,
    borderWidth: StyleSheet.hairlineWidth,
  },
});

