            accessibilityRole="button"
            accessibilityState={{ disabled: !canContinue }}
          >
            <ThemedText weight="medium" style={[typography.settingLabel, { color: "#FFFFFF" }]}>
              Save
            </ThemedText>
          </Pressable>
        </View>
      </View>
    </KeyboardAvoidingView>
  );
}

